WITH payload AS (SELECT $archive_payload$[{"id":"c4cb71fb-da7b-5783-9124-200d023a977e","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج حبوب محظورة -حيازة حشيش بقصد التعاطي وتعاطيه له -تعاطي احلبوب احملظورة -التستر -التوسط يف ترويج احلبوب احملظورة -إقامة حد املسكر -التعزير بالسجن واجللد والغرامة واملنع من السفر واملصادرة وإسقاط شريحة اجلوال .","document_number":"34246749","case_number":"3452378","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/20","year":"1434","subject":"مخدرات -ترويج حبوب محظورة -حيازة حشيش بقصد التعاطي وتعاطيه له -تعاطي احلبوب احملظورة -التستر -التوسط يف ترويج احلبوب احملظورة -إقامة حد املسكر -التعزير بالسجن واجللد والغرامة واملنع من السفر واملصادرة وإسقاط شريحة اجلوال .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34246749 :‬تاريخه ‪1434/6/20:‬هـ‬\n                          ‫رقم الدعوى ‪3452378:‬‬\n         ‫رقم قرار التصديق من محكمة اإلستئناف ‪:‬‬\n                 ‫‪ 34380279‬تاريخه ‪1434/12/17‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬ترويــج حبــوب محظــورة‪ -‬حيــازة حشــيش بقصــد التعاطــي‬\n      ‫وتعاطيه له ‪ -‬تعاطي احلبوب احملظورة ‪ -‬التســتر‪ -‬التوســط يف ترويج‬\n      ‫احلبــوب احملظــورة ‪ -‬إقامــة حــد املســكر ‪ -‬التعزيــر بالســجن واجللــد‬\n         ‫والغرامــة واملنــع مــن الســفر واملصــادرة وإســقاط شــريحة اجلــوال ‪.‬‬\n\n\n\n\n                                                       ‫‪ -1‬قاعدة املرء مؤاخذ بإقراه‪.‬‬\n                                                              ‫‪ -2‬قاعده ال عذر ملن أقر‪.‬‬\n      ‫‪ -3‬قــول اهلل تعالــى (يــا أيهــا الذيــن آمنــوا إمنــا اخلمــر وامليســر واألنصــاب‬\n             ‫واألزالم رجــس مــن عمــل الشــيطان فاجتنبــوه لعلكــم تفلحــون )‪.‬‬\n      ‫‪ -4‬قولــه صلــى اهلل عليــه وســلم (كل مســكر خمــر وكل خمــر حــرام)‬\n                                                                                 ‫رواه مسلم‬\n      ‫‪ -5‬قــال املــرداوي يف االنصــاف (‪( :)438/8‬وأبــو العبــاس يــرى أن‬\n      ‫حكمهــا حكــم الشــراب املســكر يف إيجــاب احلــد وهــو الصحيــح إن‬\n                                                                                 ‫أســكر)‪.‬‬\n      ‫‪ -6‬قــال شــيخ االســام يف الفتــاوي (‪( :)198/34‬وكذلــك احلشيشــة‬\n      ‫املســكرة يجــب فيهــا احلــد ومــن ظــن أن احلشيشــة ال تســكر وإمنــا تغيــب‬\n      ‫العقــل بــا لــذة فلــم يعــرف حقيقــه أمرهــا )‪ .‬وقــال يف موضــع آخــر )‬\n       ‫الصحيــح أن احلشيشــة مســكرة كالشــراب )‪ .‬الفتــاوى (‪.)214/34‬‬\n      ‫‪ -7‬قــال ابــن حجــر ‪( :‬واســتدل مبطلــق قولــه صلى اهلل عليه وســلم « كل‬\n‫‪437‬‬\n\f‫مســكر حــرام « علــى حتــرمي مــا يســكر ولــو لــم يكــن شــراب ًا فيدخــل‬\n  ‫يف ذلــك احلشيشــة وغيرهــا وقــد جــزم النــووي وغيــره بأنهــا مســكرة)‪.‬‬\n‫‪ -8‬وألن الصحابــة رضــي اهلل عنهــم ملــا تشــاوروا يف عهــد عمر رضي اهلل‬\n‫عنــه حــن أكثــر النــاس مــن شــرب اخلمــر قــال عبدالرحمــن بــن عــوف‬\n   ‫رضــي اهلل عنــه ‪(:‬أخــف احلــدود ثمانــون فوافــق علــى ذلــك الصحابــة)‪.‬‬\n‫‪ -9‬قــرار هيئــة كبــار العلمــاء رقــم (‪ )53‬وتاريــخ ‪1397/04/04‬ه ـ‬\n‫املتضمــن ‪ :‬بــأن عقوبــة شــارب اخلمــر احلــد ال التعزيــر باإلجمــاع ‪ ،‬كمــا‬\n                                                   ‫قــرر أنــه ثمانــون جلــدة ‪.‬‬\n‫‪ -10‬يســوغ اجلمــع بــن احلــد والتعزيــر إذا وجــدت جنايتــن ملــا روى أحمــد‬\n‫بإســناده أن علي ـ ًا أتــى بالنجاشــي قــد شــرب خمــر ًا يف رمضــان فجلــده‬\n‫ثمانــن احلــد وعشــرين ســوط ًا لفطــرة يف رمضــان ‪ .‬وأخرجــه أيض ـ ًا‬\n‫عبدالــرزاق وابــن أبــي شــيبه والبيهقــي ‪.‬كشــاف القنــاع (‪.)112/14‬‬\n‫‪ -11‬الفقــرة (‪ )1‬مــن املــادة (‪ )38‬مــن نظــام مكافحــة املخــدرات‬\n                                                        ‫واملؤثــرات العقليــة‪.‬‬\n‫‪ -12‬الفقــرة (‪ )1‬مــن املــادة (‪ )60‬مــن نظــام مكافحــة املخــدرات‬\n                                          ‫املخــدرات واملؤثــرات العقليــة‪.‬‬\n‫‪ -13‬الفقــرة (‪ )1‬مــن املــادة (‪ )62‬مــن نظــام مكافحــة املخــدرات‬\n                                          ‫املخــدرات واملؤثــرات العقليــة‪.‬‬\n         ‫‪ -14‬الفقرة (‪ )1‬من املادة (‪ )56‬من نظام مكافحة املخدرات‪.‬‬\n                                                  ‫‪ -15‬قاعدة ‪ :‬رفع الضرر‪.‬‬\n‫‪ -16‬تعميم سمو وزير الداخلية رقم (‪ )9798‬وتاريخ ‪1428/02/10‬هـ‪.‬‬\n\n                                                                                   ‫‪438‬‬\n\f      ‫ادعــى املدعــي العــام علــى املدعــى عليهــم وهــم ثالثــة ‪ ،‬األول‪ :‬ببيــع ثالث‬\n      ‫حبــات مــن حبــوب اإلمفيتامــن بقصــد االجتــار وحيــازة قطــع حشــيش‬\n      ‫بقصــد التعاطــي ‪ ،‬تعاطــي احلشــيش املخــدر واحلبــوب احملظورة ‪ ،‬الثاني‬\n      ‫‪ :‬بيــع ثــاث حبــات مــن حبــوب اإلميفتامــن بقصــد االجتــار وتعاطــي‬\n      ‫احلبــوب احملظــورة ‪ ،‬الثالــث ‪ :‬تعاطــي احلبــوب احملظــورة وتســتره علــى‬\n      ‫بيــع شــقيقه للحبــوب احملظــورة ‪،‬حيــث توفــرت معلومــات لــدى شــعبة‬\n      ‫مكافحــة املخــدرات عــن قيــام شــخص بالتوســط يف بيــع مــادة احلبــوب‬\n      ‫احملظــورة ويســتخدم اجلــوال يف ذلــك ‪ ،‬مت متكــن املصــدر مــن االتصــال‬\n      ‫عليــه وطلــب املصــدر مــن املــروج احلبــوب احملظــورة ‪ ،‬وافــق املــروج علــى‬\n      ‫ذلــك ومت تزويــد املصــدر باملبلــغ املرقــم ومت تكليــف أحــد رجــال األمــن‬\n      ‫ملرافقة املصدر ومشــاهدة عملية االســتالم والتســليم وكان ذلك حتت‬\n      ‫أنظــار الفرقــة القابضــة ‪ ،‬قــام الوســيط (املدعــى عليــه الثاني)باالتصــال‬\n      ‫علــى شــخص (املدعــى عليــه األول) وأفــاده أنــه قــادم إليــه وكان ذلــك‬\n      ‫علــى مســمع مــن رجــال األمــن ‪ ،‬بعــد الوصــول ملنــزل املدعــى عليــه األول‬\n      ‫نــزل الوســيط (املدعــى عليــه الثانــي) ودخــل أحــد النوافــذ املظلمــة ثــم‬\n      ‫رجــع وســلم رجــل األمــن حبــوب الكبتاجــون فتــم القبــض علــى الوســيط‬\n      ‫ومت مداهمــة الشــقة وضبــط املدعــى عليهمــا األول والثالــث وعثــر مــع‬\n      ‫املدعــى عليــه الثالــث املبلــغ املرقــم كمــا ضبــط داخــل الشــقة علــى تبــغ‬\n      ‫مخلــوط باحلشــيش ‪ .‬طلــب املدعــي العــام إثبــات مــا أســند اليهــم واحلكــم‬\n      ‫عليهــم بعقوبــة الســجن واجللــد والغرامــة واملنــع مــن الســفر ومصــادرة‬\n      ‫الهاتــف وإســقاط شــريحة اجلــوال واحلكــم علــى املدعــى عليــه الثالــث‬\n\n‫‪439‬‬\n\f‫لقــاء تســتره علــى أخيــه املدعــى عليــه األول يف بيــع احلبــوب احملظــورة‬\n‫وحضــر املدعــى عليــه األول والثانــي وتخلــف املدعــى عليــه الثالــث عــن‬\n‫احلضــور ‪ ،‬كمــا أقــر املدعــى عليــه األول مبــا نســب إليــه وأنكــر املدعى‬\n‫عليــه الثانــي مــا نســب إليــه وأقــر بالتوســط وأقــر املدعــى عليــه الثانــي‬\n‫بعائديــة رقــم اجلــوال لــه وجــرى االطــاع علــى أوراق املعاملــة والتقريــر‬\n‫الكيميائــي الشــرعية ‪ ،‬بنــاء علــى مــا تقــدم حكمــت احملكمــة بإدانــة‬\n‫املدعــى عليــه االول مبــا نســب اليــه مــن بيعــه لثــاث حبــات مــن حبــوب‬\n‫االمفيتامــن املنبهــة احملظــورة بقصــد االجتــار وحيازتــه لقطعــة حشــيش‬\n‫مخــدر بقصــد التعاطــي ‪ ،‬كمــا ثبــت إدانــة املدعــى عليــه الثانــي مبــا‬\n‫نســب إليــه مــن التوســط يف بيــع حبــوب االمفيتامــن وحكــم عليهمــا‬\n‫بالســجن واجللــد والغرامــة واملنــع مــن الســفر ‪ ،‬وعلــى املدعى عليــه الثاني‬\n‫مبصــادرة هاتفــه اجلــوال واســقاط شــريحته وثبــت تعاطــي املدعــى عليــه‬\n‫األول حلبــوب االمفيتامــن وتعاطيــه للحشــيش وحكــم عليــه لقــاء ذلــك‬\n‫بإقامــة حــد املســكر عليــه بجلــده ثمانــن جلــده ‪ ،‬حيــث أنــه لــم تثبــت‬\n‫إدانــة املدعــى عليــه الثانــي بتعاطــي احلبــوب املنبهــة احملظــورة وحكــم‬\n‫بإســقاط طلــب املدعــي العــام بإيقــاع العقوبــة عليــه لقــاء ذلــك‪ ،‬أفهــم‬\n‫املدعــي العــام بأنــه لــه إقامــة دعــواه علــى املدعــى عليــه الثالــث متــى مــا‬\n                        ‫وصــدق احلكــم مــن محكمــة االســتئناف‪.‬‬        ‫أحضــره ُ‬\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n‫أنــا ‪ .......‬القاضــي باحملكمــة اجلزئيــة بالدمــام ففــي يــوم األحــد املوافــق‬\n‫‪1434 /05 / 27‬ه ـ افتتحــت اجللســة الســاعة العاشــرة صباح ـ ًا بنــاء‬\n\n                                                                                         ‫‪440‬‬\n\f      ‫علــى املعاملــة احملالــة إلينــا مــن فضيلــة رئيــس احملكمــة اجلزئيــة بالدمــام‬\n      ‫برقــم ‪ .....‬وتاريــخ ‪ 1434 /02 / 02‬ه ـ واملقيــدة بــوارد مكتبنــا‬\n      ‫برقــم وتاريــخ ‪ 1434/02/02‬ه ـ واملتعلقــة بدعــوى املدعــي العــام ضــد‬\n      ‫‪ /‬ولــم يحضــر املدعــى عليــه ‪ ..... /‬وفيهــا حضــر املدعــي العــام ‪........ /‬‬\n      ‫وادعــى علــى احلاضريــن معــه ‪ ......‬ســعودي اجلنســية بالبطاقــة رقــم (‪)....‬‬\n      ‫و‪ .......‬ســعودي اجلنســية بالبطاقــة رقــم (‪ ).....‬قائــا يف دعــواه بصفتــي‬\n      ‫مدعيـ ًا عامـ ًا بدائــرة اإلدعــاء العــام لفــرع الهيئــة باملنطقــة الشــرقية أدعي‬\n      ‫علــى املذكوريــن أعــاه‪ .‬أنــه يف متــام الســاعة الثامنــة مــن مســاء الســبت‬\n      ‫املوافــق ‪1433/12/27‬ه ـ توفــرت معلومــات لــدى شــعبة مكافحــة‬\n      ‫املخــدرات بالدمــام عــن شــخص يدعــى ‪ .......‬مــن ســكان مدينــة ‪.......‬‬\n      ‫بالدمــام يقــوم بالتوســط يف مــادة احلبــوب احملظــورة ويســتخدم اجلــوال‬\n      ‫رقــم (‪ )....‬ورقمــه املصنعــي (‪ ).....‬فتــم متكــن املصــدر مــن االتصــال علــى‬\n      ‫هاتــف املــروج وطلــب املصــدر مــن املــروج حبــوب محظــورة مببلــغ مائــة‬\n      ‫ريــال فوافــق املــروج وطلــب مــن املصــدر أن يحضــر إليــه عنــد البقالــة‬\n      ‫املجــاورة ملنزلــه ومت تزويــد املصــدر باملبلــغ املرقــم ومت تكليــف أحــد‬\n      ‫رجــال األمــن ليكــون مــع املصــدر ملشــاهدة عمليــة االســتالم والتســليم‬\n      ‫وكان ذلــك حتــت أنظــار الفرقــة القابضــة وبعــد الوصــول ملدينــة العمــال‬\n      ‫قــام الوســيط باالتصــال علــى شــخص يدعــى ‪ ....‬وأفــاده أنــه قــادم إليــه‬\n      ‫وكان علــى مســمع مــن رجــل األمــن املرافــق حيــث تبــن أنــه كان بــن‬\n      ‫الوســيط و ‪ ........‬وذكــر الوســيط بأنــه وشــقيقه األكبــر يســكنان‬\n      ‫أعزبــان وبعــد الوصــول إلــى منــزل الوســيط ومعــه املبلــغ املرقــم ودخــل‬\n      ‫أحــد النوافــذ املظلمــة وبعــد مــرور دقيقتــن رجــع الوســيط وســلم رجــل‬\n      ‫األمــن عــدد(‪ )3‬ثــاث حبــات يشــتبه أن تكــون كبتاجــون ثــم علــى‬\n\n\n‫‪441‬‬\n\f‫الفــور مت القبــض علــى الوســيط الــذي اتضــح أنــه يدعــى ‪ .......‬وضبــط‬\n‫معــه جــوال مــن نــوع ‪ .......‬املســتخدم يف اجلرميــة ومت مداهمــة الشــقة‬\n‫وضبــط شــخصان األول يدعــى ‪ ..... /‬والثانــي يدعــى‪ ....... /‬وعثــر علــى‬\n‫املبلــغ املرقــم مائــة ريــال مــع (‪ )......‬وبتفتيــش الشــقة عثــر بحوشــها حتــت‬\n‫فرشــة (علــى قصاصــة ورقيــة بداخلهــا تبــغ يشــتبه أن يكــون مخلوط ـ ًا‬\n‫باحلشــيش املخــدر) بلــغ وزنهــا(‪ )0.3‬ثالثــة مــن العشــرة مــن اجلــرام أثبــت‬\n‫التقريــر الكيمــاوي الشــرعي رقــم (‪ )......‬يف ‪1434/1/11‬ه ـ احتــواء‬\n‫مــا ضبــط علــى مــادة احلشــيش املخــدر واحلبــوب األمفيتامــن احملظــور‬\n‫‪ .‬وباســتجواب املتهــم(‪ ).....‬أقــر بصحــة واقعــة الضبــط وأفــاد أنــه قــام‬\n‫باســتالم مبلــغ مرقــم لشــراء ثــاث حبــات كبتاجــون مــن املــروج وأشــار‬\n‫بأنــه يســتخدم احلبــوب احملظــورة يف الســابق وأفــاد أن اجلــوال ذا الرقــم‬\n                                              ‫( ‪ ) ......‬عائــد لــه وباســتخدامه ‪.‬‬\n‫وباســتجواب املتهــم ) (‪ ).....‬أفــاد أنــه ال عالقــة لــه بقضيــة املخــدرات وال‬\n‫يعلــم شــيئ ًا عــن شــقيقه وأقــر أنــه يســكن مع شــقيقه وأنــه كان يتعاطى‬\n‫احلبــوب احملظــورة ‪ .‬وباســتجواب املتهــم (‪ ).......‬أقــر بصحة واقعة الضبط‬\n‫وأنــه قــام بترويــج ثــاث حبــات كبتاجــون علــى أحــد األشــخاص مببلــغ‬\n‫مائــة ريــال وأن هدفــه مــن الترويــج هــو الكســب املــادي وأن مــا عثــر‬\n‫عليــه حتــت الفرشــة مــن ثالثــة مــن العشــرة مــن احلشــيش املخــدر عائــد لــه‬\n‫لقصــد التعاطــي وأنــه يتعاطــى احلبــوب احملظــورة واحلشــيش املخدريــن‬\n‫وأفــاد بأنــه ال عالقــة لشــقيقة بقضيــة املخــدرات وأقــر يف أقوالــه األوليــة‬\n                           ‫أنــه ضبــط معــه املبلــغ املرقــم وصــادق علــى ذلــك ‪.‬‬\n‫وقــد انتهــى التحقيــق إلــى اتهــام ‪ .......‬ببيــع ثــاث حبــات مــن حبــوب‬\n‫االمفيتامــن املنبهــة واحملظــورة بقصــد االجتــار وحيــازة قطعــة حشــيش‬\n\n\n                                                                                       ‫‪442‬‬\n\f      ‫مخــدر تــزن (‪ )0.3‬ثالثــة مــن العشــرة مــن اجلــرام مــن احلشــيش املخــدر‬\n      ‫لقصــد التعاطــي وتعاطــي احلشــيش املخــدر واحلبــوب احملظــور ة ‪ .‬واتهــام‬\n      ‫(‪ ).....‬ببيــع ثــاث حبــات مــن حبــوب االمفيتامــن املنبهــة واحملظــورة‬\n      ‫بقصــد االجتــار وتعاطــي احلبــوب احملظــورة ‪ .‬واتهــام (‪ )......‬بتعاطــي‬\n      ‫احلبــوب احملظــورة وتســتره علــى بيــع شــقيقه (‪ ).....‬احلبــوب احملظــورة ‪.‬‬\n                                                        ‫وذلك لألدلة والقرائن التالية ‪:‬‬\n      ‫‪ -1‬محضــر القبــض والضبــط والتفتيــش املــدون علــى الصفحــة رقــم‬\n                               ‫(‪ )13-12‬مــن ملــف ضبــط إجــراءات االســتدالل‬\n      ‫‪ -2‬مــا جــاء يف أقوالــه حتقيق ـ ًا املرفقــة يف اللفتــن رقــم ( ‪) 22-17‬‬\n      ‫وأقوالهــم األوليــة املدونــة علــى الصفحــات رقــم (‪ )23-21‬مــن ملــف‬\n                                ‫ضبــط إجــراءات قضيــة مخــدرات لفــة رقــم (‪)1‬‬\n                                    ‫‪ -3‬محضر التحريز املرفق على اللفة رقم (‪)5‬‬\n                  ‫‪ -4‬التقرير الكيماوي الشرعي املرفق على اللفة رقم ( ‪.) 23‬‬\n      ‫وحيــث إن مــا أقــدم عليــه املذكــورون‪ -‬وهــم بكامــل أهليتهــم املعتبــرة‬\n      ‫شــرع ًا ‪ -‬فعــل محــرم ومعاقــب عليــه شــرع ًا ونظام ـ ًا أطلــب إثبــات مــا‬\n      ‫أســند إليهــم وفق ـ ًا للفقــرة (‪ )2‬مــن املــادة (‪ )3‬مــن نظــام مكافحــة‬\n                                             ‫املخــدرات واحلكــم عليهــم مبــا يلــي ‪:‬‬\n      ‫‪ -1‬عقوبــة الســجن واجللــد والغرامــة الــواردة يف الفقــرة (‪ )1‬مــن املــادة‬\n      ‫(‪ )38‬مــن نظــام مكافحــة املخــدرات ووفقــا للفقــرة رقــم (‪ )1‬مــن‬\n      ‫املــادة(‪ )62‬مــن ذات النظــام بتطبيــق العقوبــة األشــد بحــق املتهمــن (و)‬\n      ‫والتشــديد عليهمــا وفق ـ ًا للفقــرة رقــم (‪/2‬ج) مــن املــادة (‪ )38‬خلطــورة‬\n                       ‫املــادة املروجــة والتشــديد علــى(‪ ).....‬كونــه عســكري ًا ‪.‬‬\n      ‫‪ -2‬عقوبــة الســجن الــواردة يف الفقــرة (‪ )1‬مــن املــادة (‪ )41‬مــن نظــام‬\n\n\n‫‪443‬‬\n\f                                               ‫مكافحــة املخــدرات للمتهــم ‪.‬‬\n‫‪ -3‬منعهــم مــن الســفر وفق ـ ًا للفقــرة (‪ )1‬مــن املــادة (‪ )56‬مــن نظــام‬\n                                                         ‫مكافحــة املخــدرات ‪.‬‬\n‫‪4‬ـ مصــادرة الهاتــف اجلــوال العائــد للمتهــم (‪ )......‬املوصــوف يف الدعــوى‬\n‫مــع إســقاط شــريحة الهاتــف النقــال املوصوفــة وعــدم صرفهــا لنفــس‬\n‫املتهــم وفق ـ ًا لتعميــم ســمو وزيــر الداخليــة رقــم (‪ )9798‬وتاريــخ‬\n                                                            ‫‪1428/2/10-9‬ه ـ ‪.‬‬\n‫‪5‬ـ احلكــم علــى املتهــم بعقوبــة تعزيريــة تزجــره وتــردع غيــره لقــاء تســتره‬\n                                       ‫علــى أخيــه يف بيــع احلبــوب احملظــورة ‪.‬‬\n‫وبــاهلل التوفيــق هــذه دعــواي وبعــرض الدعــوى علــى املدعــى عليــه‬\n‫ا مــا ذكــره املدعــي العــام مــن أننــي قمــت‬   ‫(املــروج)‪ ........ /‬أجــاب قائ ـ ً‬\n‫ببيــع ثــاث حبــات مــن حبــوب االمفيتامــن املنبهــة احملظــورة بقصــد‬\n‫االجتــار وأننــي قمــت بحيــازة قطعــة حشــيش مخــدر بلــغ وزنهــا (‪)0,3‬‬\n‫ثالثــة مــن العشــرة مــن اجلــرام بقصــد التعاطــي وأننــي أتعاطــى احلشــيش‬\n         ‫املخــدر واحلبــوب احملظــورة كل ذلــك صحيــح هكــذا أجــاب ‪.‬‬\n‫ا‬\n‫وبعــرض الدعــوى علــى املدعــى عليــه (الوســيط) ‪ ......./‬أجــاب قائ ـ ً‬\n‫مــا ذكــره املدعــي العــام مــن أننــي قمــت ببيــع ثــاث حبــات مــن حبــوب‬\n‫االمفيتامــن املنبهــة واحملظــورة فغيــر صحيــح والصحيــح أنــي توســطت‬\n‫يف بيعهــا حيــث قمــت بشــراء ثــاث حبــات من حبــوب االمفيتامــن املنبهة‬\n‫واحملظــورة مــن املدعــى عليــه (املــروج) ‪ ..... /‬ثــم قمت بتســليم تلك احلبات‬\n‫للمصــدر وتســليم املدعــى عليــه (املــروج) ‪ ......./‬املبلــغ ومــا ذكــره مــن‬\n‫أننــي أتعاطــى احلبــوب احملظــورة فغيــر صحيــح ثــم جــرى ســؤال املدعــى‬\n‫عليــه (شــقيقه)‪ ..../‬عــن رقــم اجلــوال (‪ ).....‬فأجــاب هــذا الرقــم عائــد لــي‬\n\n\n                                                                                         ‫‪444‬‬\n\f      ‫وهــو الــذي اتصــل علــي املصــدر منــه طالب ـ ًا املخــدرات هكــذا أجــاب‬\n      ‫ثــم جــرى ســؤال املدعــي العــام هــل لديــك بينــة علــى دعــواك فيمــا يتعلــق‬\n      ‫ا ليــس لــدي‬    ‫بتعاطــي املدعــى عليــه للحبــوب احملظــورة فأجــاب قائ ـ ً‬\n      ‫بينــة ســوى مــا يف أوراق املعاملــة ثــم رفعــت اجللســة لطلــب املدعــى عليــه‬\n      ‫وتأجلــت إلــى يــوم االثنــن املوافــق ‪1434/06/19‬ه ـ الســاعة التاســعة‬\n      ‫صباح ـ ًا واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                   ‫وســلم حــرر يف ‪1434/05/27‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــدة وبعــد ففــي هــذا اليــوم األربعــاء ‪1434/6/7‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة العاشــرة صباح ـ ًا وفيهــا حضــر املدعــي العــام وحضــر‬\n      ‫املدعــى عليــه ‪ ......‬واملدعــى عليــه ‪ ......‬ولــم يحضــر املدعــى عليــه ‪ ....‬وقــد‬\n      ‫جــرى اطالعــي علــى أوراق املعاملــة كمــا جــرى اطالعــي علــى التقريــر‬\n      ‫الكيمــاوي الشــرعي رقــم وتاريــخ ‪1434/1/11‬ه ـ املرفــق باملعاملــة لفــة‬\n      ‫رقــم ‪ 23‬واملتضمــن ثبــوت ايجابيــة عينــة احلبــوب املضبوطــة جميعـ ًا كل‬\n      ‫علــى حــدة ملــادة االمفيتامــن احملظــورة وثبــوت احتــواء عينــة القطعــة‬\n      ‫املضبوطــة ملــادة احلشــيش املخــدر فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n      ‫واإلجابــة ونظــرا ملــا قــرره الطرفــان ومــا مت رصــده وضبطــه أعــاه وبعــد‬\n      ‫االطــاع علــى أوراق املعاملــة ودراســتها وبنــاء ملصادقــة املدعــى عليــه ‪....‬‬\n      ‫ا واملــرء مؤاخــذ‬    ‫ملــا نســب إليــه يف دعــوى املدعــي العــام جملــة وتفصي ـ ً‬\n      ‫بإقــرار وال عــذر ملــن أقــر ونظــر ًا إلــى إقــرار املدعــى عليــه ‪ .....‬بالتوســط‬\n      ‫يف بيــع املــواد املخــدرة واملــرء مؤاخــذ بإقــراره وال عــذر ملــن أقر والتوســط‬\n      ‫مــن األفعــال اجلرميــة التــي تشــملها الفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪)38‬‬\n      ‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة وبنــاء علــى مــا يلــي ‪:‬‬\n      ‫(‪ )1‬بنــاء علــى أن مــا قــام بــه املدعــى عليــه هــو محــرم شــرعا ومجــرم‬\n\n\n‫‪445‬‬\n\f                                                                                ‫نظامــا‬\n‫(‪ )2‬بنــاء علــى أن تعاطــي احلشــيش املخــدر يــؤدي إلــى اإلســكار‪ ،‬وقــد‬\n‫نــص أهــل العلــم علــى إقامــة احلــد علــى متنــاول احلشــيش كمــا ذكــر‬\n‫املــرداوي يف اإلنصــاف يف (‪ )438/8‬حيــث قــال ‪ »:‬وأبــو العبــاس يــرى أن‬\n‫حكمهــا حكــم الشــراب املســكر يف إيجــاب احلــد وهــو الصحيــح إن‬\n                          ‫أســكرت أو كثيرهــا وإال حرمــت وعــزر فقــط»‬\n‫وقــال شــيخ اإلســام ‪ « :‬وكذلــك احلشيشــة املســكرة يجــب فيهــا احلــد‬\n‫ومــن ظــن أن احلشيشــة ال تســكر وإمنــا تغيــب العقــل بــا لــذة فلــم يعــرف‬\n‫حقيقــة أمرهــا» (‪ ،)198/34‬وقــال‪« :‬الصحيــح أن احلشيشــة مســكرة‬\n                                              ‫كالشــراب » الفتــاوى (‪)214/34‬‬\n‫قــال ابــن حجــر ‪« :‬واســتدل مبطلــق قولــه صلــى اهلل عليــه وســلم ‪( :‬كل‬\n‫مســكر حــرام) علــى حتــرمي مــا يســكر ولــو لــم يكــن شــرابا فيدخــل‬\n ‫يف ذلــك احلشيشــة وغيرهــا وقــد جــزم النــووي وغيــره بأنهــا مســكرة »‬\n                                                              ‫فتح الباري (‪)45/10‬‬\n‫واهلل تعالــى يقــول‪ ( :‬يــا أيهــا الذيــن آمنــوا إمنــا اخلمــر وامليســر واألنصــاب‬\n‫واألزالم رجــس مــن عمــل الشــيطان فاجتنبــوه لعلكــم تفلحــون ) ولقولــه‬\n‫صلــى اهلل عليــه وســلم‪ ( :‬كل مســكر خمــر وكل خمــر حــرام )رواه‬\n‫مســلم «وألن الصحابة ـ رضي اهلل عنهم ملا تشــاوروا يف عهد عمر رضي‬\n‫اهلل عنــه حــن أكثــر النــاس مــن شــربه‪ ،‬قــال عبــد الرحمــن بــن عــوف‬\n‫رضــي اهلل عنــه‪ :‬أخــف احلــدود ثمانــون فوافــق علــى ذلــك الصحابــة» أ‪.‬ه ـ‬\n                                                        ‫الشــرح املمتــع (‪)293/14‬‬\n‫(‪ )3‬بنــاء علــى قــرار هيئــة كبــار العلمــاء رقــم ‪ 53‬وتاريــخ ‪1397/4/4‬ه ـ‬\n‫والــذي تضمــن بــأن عقوبــة شــارب اخلمــر احلــد ال التعزيــر باإلجمــاع كمــا‬\n\n\n                                                                                          ‫‪446‬‬\n\f                                                         ‫قــرر أنــه ثمانــون جلــدة ‪.‬أ‪.‬هـ‬\n      ‫(‪ )4‬بنــاء علــى إلــى أنــه يســوغ اجلمــع بــن احلــد والتعزيــر إذا وجــد جنايتــن‬\n      ‫ملــا روى أحمــد بإســناده أن علي ـ ًا أتــي بالنجاشــي قــد شــرب خمــر ًا يف‬\n      ‫رمضــان فجلــده ثمانــن احلــد وعشــرين ســوط ًا لفطــره يف رمضــان‬\n      ‫وأخرجــه أيضـ ًا عبدالــرزاق وابــن أبــي شــيبة والبيهقــي (كشــاف القنــاع‬\n                                                                               ‫‪)112/14‬‬\n      ‫(‪ )5‬بنــاء علــى الفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )38‬مــن نظــام مكافحــة‬\n                                                        ‫املخــدرات واملؤثــرات العقلية‬\n      ‫(‪ )6‬بنــاء علــى خلــو ســجل املدعــى عليهمــا مــن الســوابق ونظــرا لقلــة‬\n                    ‫الكميــة ونظــرا ملــا ظهــر لــي مــن أخــاق املدعــى عليهمــا‬\n      ‫(‪ )7‬بنــاء علــى الفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )60‬مــن نظــام مكافحــة‬\n      ‫املخــدرات واملؤثــرات العقليــة والتــي تقتضــي النــزول عــن احلــد األدنــى‬\n            ‫مــن عقوبــة الســجن املنصــوص عليهــا يف املــادة (الثامنــة والثالثــن)‬\n      ‫(‪ )8‬وبنــاء علــى الفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )62‬مــن نظام مكافحة‬\n      ‫املخــدرات واملؤثــرات العقليــة واملتضمنــة بأنــه إذا ارتكــب شــخص عــدة‬\n      ‫جرائــم معاقــب عليهــا مبوجــب أحــكام نظــام مكافحــة املخــدرات‬\n      ‫واملؤثــرات العقليــة قبــل صــدور حكــم نهائــي بحقــه عــن أي واحــدة منهــا‬\n      ‫وجــب محاكمتــه علــى اجلرميــة ذات العقوبــة األشــد واحلكــم بعقوبتهــا‬\n                                                                            ‫دون غيرهــا‬\n      ‫(‪ )9‬ونظــر ًا إلــى أن تأجيــل احلكــم يف القضيــة إلــى حــن حضــور املدعــى‬\n      ‫عليــه ‪ ......‬فيــه ضــرر علــى البقيــة والشــريعة اإلســامية جــاءت لرفــع‬\n                                                          ‫الضــرر ولــكل مــا ســبق ‪:‬‬\n      ‫(أوالً)‪:‬ثبــت لــدي إدانــة املدعــى عليــه ‪ ......‬مبــا نســب إليــه مــن بيعــه‬\n\n\n‫‪447‬‬\n\f‫ثــاث حبــات مــن حبــوب االمفيتامــن املنبهــة واحملظــورة بقصــد االجتــار‬\n‫وحيازتــه لقطعــة حشــيش مخــدر بلــغ وزنهــا (‪ )0.3‬ثالثــة مــن العشــرة‬\n‫مــن اجلــرام بقصــد التعاطــي كمــا ثبــت لــدي إدانــة املدعــى عليــه الثانــي‬\n‫(الوســيط)‪ ....... /‬مبا نســب إليه من التوســط يف بيع حبوب االمفيتامني‬\n‫املنبهــة واحملظــورة وبذلــك حكمــت وحكمــت علــى املدعــى عليهمــا‬\n                                                              ‫لقــاء ذلــك مبــا يلــي ‪:‬‬\n‫(‪ )1‬حكمــت علــى املدعــى عليهمــا بســجن كل واحــد منهمــا مــدة‬\n‫ســنتني ونصــف يحتســب منهــا مــا أمضــاه كل واحــد منهمــا موقوفــا‬\n‫يف هــذه القضيــة وذلــك وفقــا للفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )38‬مــن‬\n‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ووفق ـ ًا للفقــرة رقــم (‪)1‬‬\n‫مــن املــادة رقــم (‪ )60‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ‪.‬‬\n‫(‪ )2‬حكمــت علــى املدعــى عليهمــا بجلــد كل واحــد منهمــا مائتــي‬\n‫جلــدة علــى دفعــات كل دفعــة خمســون جلــدة بــن كل دفعــة والتــي‬\n‫تليهــا عشــرة أيــام علــى أن يكــون جلــد احلــد للمدعــى عليــه ‪ .....‬قبــل أول‬\n                                   ‫دفعــة يف جلــد التعزيــر بخمســة عشــر يومــا‬\n‫وذلــك وفقــا للفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )38‬مــن نظــام مكافحــة‬\n                                                   ‫املخــدرات واملؤثــرات العقليــة‪.‬‬\n‫(‪ )3‬حكمــت علــى املدعــى عليهمــا بــأن يدفــع كل واحــد منهمــا غرامــة‬\n‫ماليــة وقدرهــا ألــف ريــال وذلــك وفقــا للفقــرة رقــم (‪ )1‬مــن املــادة رقــم‬\n                  ‫(‪ )38‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ‪.‬‬\n‫(‪ )4‬حكمــت علــى املدعــى عليهمــا ‪ .....‬مبنــع كل واحــد منهمــا مــن‬\n‫الســفر إلــى خــارج اململكــة بعــد انتهــاء عقوبــة الســجن ملــدة ســنتني‬\n‫ونصــف وفقــا للفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )56‬مــن نظــام مكافحــة‬\n\n\n                                                                                           ‫‪448‬‬\n\f                                                    ‫املخــدرات واملؤثــرات العقليــة ‪.‬‬\n      ‫(‪ )5‬حكمــت علــى املدعــى عليــه ‪ ......‬مبصــادرة هاتفــه اجلــوال املســتخدم‬\n      ‫يف الترويــج واملذكــور يف الئحــة دعــوى املدعــي العــام وذلــك وفقــا للفقرة‬\n      ‫رقــم (‪ )1‬مــن املــادة رقــم (‪ )53‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                                  ‫العقلية‪.‬‬\n      ‫(‪ )6‬حكمــت علــى املدعــى عليــه ‪ ......‬بإســقاط شــريحته املســتخدمة‬\n      ‫يف الترويــج واملذكــورة يف الئحــة دعــوى املدعــي العــام وعــدم صرفهــا‬\n      ‫للمتهــم نفســه وذلــك بنــاء علــى تعميــم ســمو وزيــر الداخليــة رقــم ( ‪)9798‬‬\n                                                          ‫وتاريــخ ‪1428/2/10-9‬هــ‪.‬‬\n      ‫(ثاني ـاً)‪ :‬ثبــت لــدي إدانــة املدعــى عليــه االول (املــروج)‪ ...../‬مبــا نســب‬\n      ‫إليــه مــن تعاطيــه للحبــوب احملظــورة وتعاطيــه للحشــيش املخــدر وبذلــك‬\n      ‫حكمــت علــى املدعــى عليــه لقــاء ذلــك حــدا بجلــده ثمانــن جلــدة دفعــة‬\n                             ‫واحــدة يف مــكان عــام إقامــة حلــد املســكر عليــه ‪.‬‬\n      ‫(ثالث ـاً)‪ :‬لــم يثبــت لــدي إدانــة املدعــى عليــه الثانــي (الوســيط) ‪...../‬‬\n      ‫بتعاطيــه للحبــوب املنبهــة واحملظــورة وبذلــك حكمــت وحكمــت‬\n      ‫بإســقاط طلــب املدعــي العــام إيقــاع العقوبــة علــى املدعــى عليــه لقــاء‬\n                                                             ‫ذلــك لعــدم إثباتــه ذلــك ‪.‬‬\n      ‫(رابع ـاً)‪ :‬أفهمــت املدعــي العــام بأنــه علــى دعــواه ضــد املدعــى عليــه‬\n                              ‫الثالــث (شــقيق املــروج) ‪ ....../‬متــى مــا احضــره ‪.‬‬\n      ‫بعــرض احلكــم علــى الطرفــن قــرر املدعــى عليهمــا قناعتهمــا باحلكــم‬\n      ‫وقــرر املدعــي العــام االعتــراض علــى احلكــم بالئحــة اعتراضيــة فأجبتــه‬\n      ‫لطلبــه وأفهمــت املدعــي العــام بــأن عليهــم مراجعــة احملكمــة يف يــوم‬\n      ‫األربعــاء املوافــق ‪1434 /6 / 14‬ه ـ الســتالم نســخة مــن احلكــم‬\n\n\n‫‪449‬‬\n\f‫لتقــدمي الئحتــه االعتراضيــة خــال ثالثــن يومــا مــن تاريــخ االســتالم وإال‬\n‫ســقط حقــه يف طلــب االســتئناف وختمــت يف الســاعة العاشــرة والنصــف‬\n‫صباح ـ ًا وعلــى ذلــك جــرى التوقيــع وبــاهلل التوفيــق وصلــى اهلل وســلم‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434 / 6 /7‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن النبــي بعــده وبعــد ففــي‬\n‫هــذا اليــوم األربعــاء املوافــق ‪1434/07/12‬ه ـ افتتحــت اجللســة يف‬\n‫الســاعة العاشــرة صباحــا وفيهــا حضــر املدعــي العــام وجــرى تســليمه‬\n‫نســخة مصــورة مــن قــرار احلكــم وللمعلوميــة فقــد جــرى حتريــره‬\n‫وختمــت اجللســة يف الســاعة العاشــرة والنصــف صباح ـ ًا وعلــى ذلــك‬\n‫جــرى التوقيــع وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى‬\n                         ‫آلــه وصحبــه وســلم حــرر يف ‪1434 /07/ 12‬هــ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ففــي‬\n‫االربعــاء يــوم املوافــق ‪14 34/ 08/24‬ه ـ افتتحــت اجللســة الســاعة‬\n‫العاشــرة صباحــا وفيهــا قــد انتهــت املــدة املنصــوص عليهــا يف املــادة‬\n‫الرابعــة والتســعني بعــد املائــة مــن نظــام اإلجــراءات اجلزائيــة ولــم يتقــدم‬\n‫املدعــي العــام بالئحتــه االعتراضيــة خــال هــذه املــدة لــذا قــررت رفــع‬\n‫كامــل املعاملــة حملكمــة االســتئناف وفقــا ملــا نصــت عليــه اخلامســة‬\n‫والتســعون بعــد املائــة مــن نظــام اإلجــراءات اجلزائيــة وللمعلوميــة فقــد‬\n‫جــرى حتريــره وختمــت يف الســاعة العاشــرة والنصــف صباحــا وعلــى‬\n‫ذلــك جــرى التوقيــع وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد‬\n                   ‫وعلــى آلــه وصحبــه وســلم حــرر يف ‪14 34 /08/24‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده و بعــد ففــي يــوم األحــد املوافــق ‪ 1435/01/21‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 01:00‬وفيهــا عــادت املعاملــة مــن محكمــة‬\n\n\n                                                                                       ‫‪450‬‬\n\f      ‫االســتئناف باملنطقــة الشــرقية بخطــاب رئيــس محكمة االســتئناف رقم‬\n      ‫وتاريــخ ‪ 1435/01/04‬ه ـ وبرفقهــا القــرار رقــم وتاريخ ‪1434/12/17‬‬\n      ‫ه ـ الصــادر مــن قضــاة الدائــرة اجلزائيــة الثانيــة يف محكمــة االســتئناف‬\n      ‫باملنطقــة الشــرقية وهــم فضيلــة الشــيخ‪ .......... /‬وفضيلــة الشــيخ ‪/‬‬\n      ‫‪ ............‬وفضيلــة الشــيخ ‪ ........... /‬واملتضمــن املصادقــة علــى احلكــم‬\n      ‫و للمعلوميــة فقــد جــرى حتريــره وختمــت يف الســاعة ‪ 01:15‬وبــاهلل‬\n      ‫التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آله وصحبــه أجمعني‬\n                                                      ‫حــرر يف ‪ 1435/01/21‬ه ـ‬\n\n\n\n\n‫‪451‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":437,"source_page_end":451,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"5c7c82212048d87a83b07c87f86d36eb35df26925cd24426a5ecb5b6a4280434","normalized_text_hash":"b4bf90fe7a9c38d5d61ddb4e930fbf669f5264f638c4bfe8f5a964cfe05ec861","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p437-34246749"},{"id":"63042e57-efa9-5737-b8b9-5255dde68657","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلبوب احملظورة -إقرار -التعزير بالسجن واجللد والغرامة واإلبعاد واملصادرة وإلغاء الشريحة.","document_number":"3430461","case_number":"3457390","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/5","year":"1434","subject":"مخدرات -ترويج احلبوب احملظورة -إقرار -التعزير بالسجن واجللد والغرامة واإلبعاد واملصادرة وإلغاء الشريحة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"  ‫رقم الصك‪ 3430461:‬تاريخه ‪1434/2/5:‬هـ‬\n                   ‫رقم الدعوى‪3457390:‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34173619‬تاريخه‪1434/3/28 :‬هـ‬\n\n\n‫مخــدرات ‪ -‬ترويــج احلبــوب احملظــورة ‪ -‬إقــرار ‪ -‬التعزيــر بالســجن‬\n         ‫واجللــد والغرامــة واإلبعــاد واملصــادرة وإلغــاء الشــريحة‪.‬‬\n\n\n\n\n                                         ‫‪ -1‬قوله تعالى ‪َ ( :‬و َل َت ْق ُت ُلوا َأ ْن ُف َس ُك ْم )‪.‬‬\n              ‫ض َب ْع َد ِإ ْص َل ِح َها )‪.‬‬       ‫‪ -2‬قوله تعالى ( َو َل ُت ْف ِس ُدوا ِف ْ َ‬\n                                            ‫ال ْر ِ‬\n         ‫‪ -3‬املادة (‪ )38‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n         ‫‪ -4‬املادة (‪ )56‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n         ‫‪ -5‬املادة (‪ )60‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n         ‫‪ -6‬املادة (‪ )53‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام علــى املدعــى عليــه بترويجــه عــدد مــن احلبــوب‬\n‫احملظــورة وطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم عليــه بالســجن‬\n‫واجللــد والغرامــة واإلبعــاد ومصــادرة اجلــوال وإلغــاء الشــريحة تطبيق ـ ًا‬\n‫ألحــكام نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ‪ ،‬حيــث إنــه‬\n‫ورد لفرقــة مكافحــة املخــدرات معلومــات مــن مصادرهــم الســرية‬\n‫عــن وجــود شــخص يقــوم بترويــج احلبــوب احملظــورة ‪ ،‬فاســتعد املصــدر‬\n‫وقــام باالتصــال باملدعــى عليــه (املــروج) وطلــب منــه ‪ 25‬حبــة مــن حبــوب‬\n\n                                                                                                      ‫‪452‬‬\n\f      ‫الكبتاجــون ‪ ،‬واتفــق معــه علــى مبلــغ ‪ 750‬ريــال وبعــد إجــراء عمليــة‬\n      ‫التســليم والتســلم مت القبــض علــى املدعــى عليــه ‪ ،‬وأثبــت التقريــر‬\n      ‫الكيميائــي الشــرعي إيجابيــة العينــة املرســلة ملــادة اإلمفتامــن ‪ ،‬صادق‬\n      ‫املدعــى عليــه علــى مــا هــو منســوب إليــه وبنــاء علــى مــا تقــدم حكمــت‬\n      ‫احملكمــة بتعزيــر املدعــى عليــه بالســجن ملــدة ســنة وجلــده أربعمائــة‬\n      ‫جلــدة وتغرميــه مبلــغ أربعــة االف ريــال وإبعــاده عــن البــاد ومصــادرة‬\n      ‫جوالــه وإلغــاء الشــريحة وبعــرض احلكــم علــى طــريف الدعــوى قنــع بــه‬\n      ‫املدعــى عليــه وقــرر املدعــي العــام االعتــراض دون الئحــة وصــدق احلكم‬\n                                                        ‫مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمد هلل وحده وبعد فلدي أنا ‪ ......‬القاضي يف احملكمة اجلزائية ‪......‬‬\n      ‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيس احملكمــة اجلزائية ‪......‬‬\n      ‫برقم ‪ ......‬وتاريخ ‪ ......‬املقيدة باحملكمة برقم ‪ ......‬وتاريخ ‪ ......‬ففي يوم‬\n      ‫الثالثــاء املوافــق ‪ ......‬ه ـ افتتحــت اجللســة األولــى الســاعة ‪ 08 : 30‬وفيهــا‬\n      ‫حضــر املدعــي العــام ‪ ......‬املوجــه باخلطــاب رقــم ‪ ......‬يف ‪ ......‬وادعــى علــى‬\n      ‫احلاضــر معــه الســجني‪ ....../‬مينــي اجلنســية بالبطاقــة البديلــة رقــم(‪)......‬‬\n      ‫حيــث أنــه بتاريــخ ‪ ......‬وأثنــاء قيــام فرقــة مكافحــة املخــدرات بعملهــم‬\n      ‫املعتــاد بصبيــا وردتهــم معلومــات مــن أحــد مصادرهــم الســرية يخبــر عــن‬\n      ‫وجــود شــخص يقــوم ببيــع احلبــوب احملظــورة يف قريــة العطنــي مبحافظــة‬\n      ‫صبيــا واســتعد املصــدر علــى أن يقــوم باالتصــال علــى املــروج ‪ ،‬واتصــل‬\n      ‫املصــدر علــى املــروج (املدعــى عليــه) علــى جوالــه رقــم (‪ )......‬وطلــب منــه‬\n      ‫عــدد (‪25‬حبــة) خمســة وعشــرين حبــة مــن حبــوب الكبتاجــون واتفــق‬\n‫‪453‬‬\n\f‫معــه علــى مبلــغ ســبعمائة وخمســن ريــال‪ ،‬وذكــر املصــدر بأنــه ســوف‬\n‫يرســل لــه أخــوه الســتالم احلبــوب‪ ،‬وكان اجلــوال علــى املكبــر وعلــى‬\n‫مســمع مــن أفــراد الفرقــة ‪ ،‬عليــه مت تكليــف فــردان وتزويدهمــا باملبلــغ‬\n‫احلكومــي املرقــم وتوجهــا إلــى املــروج ‪،‬وعنــد الوصــول للموقــع خــرج‬\n‫إليهمــا املتهــم وأعطــى الفــرد كيــس صغيــر بداخلــه عــدد (‪25‬حبــة)‬\n‫خمســة وعشــرين حبــة يشــتبه أن تكــون مــن حبــوب الكبتاجــون‬\n‫احملظــورة ‪ ،‬وأثنــاء انتظــاره الســتالم املبلــغ أعطيــت اإلشــارة ومت القبــض‬\n‫عليــه ‪.‬أثبــت التقريــر الكيميائــي الشــرعي رقــم (‪/......‬س ‪ 2‬لعــام ‪)......‬‬\n‫الصــادر مــن مركــز الســموم والكيميــاء الشــرعية مبنطقــة ‪......‬‬\n‫إيجابيــة العينــة املرســلة مــن ســتة أقــراص بيضــاء اللــون حتمــل عالمــة‬\n‫الكبتاجــون ملــادة الالمفيتامــن احملظــورة ‪ ،‬واملدرجــة يف اجلــدول رقــم‬\n‫(‪ )1‬فئــة (أ) امللحــق بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n‫الصــادر باملرســوم امللكــي رقــم م‪ 39/‬يف ‪1426/7/8‬ه ـ وباســتجواب‬\n‫املدعــى عليــه أقــر بقيامــه بالبيــع والترويــج وأن الكميــة املضبوطــة معــه‬\n‫مــن احلبــوب احملظــورة البالــغ عددهــا (‪25‬حبــة ) تعــود لشــخص حبشــي‬\n‫ال يعرفــه قــام بأخذهــا منــه لكــي يقــوم بإيصالهــا إلــى األفــراد حيــث‬\n‫ذكــر لــه احلبشــي أنهــم أصدقــاؤه فقــام بإيصالهــا لهــم ‪ ،‬ومت القبــض‬\n‫‪ ،‬وصــادق علــى أقوالــه بذلــك حتقيقــا‪ .‬ومت إيقافــه اســتناد ًا للقــرار‬\n‫الــوزاري رقــم (‪ )1900‬يف ‪1428/7/9‬ه ـ كــون جرميتــه مــن اجلرائــم‬\n‫املوجبــة للتوقيــف‪ .‬وقــد أســفر التحقيــق مــع املدعــى عليــه باتهامــه ببيــع‬\n‫مــا عــدده (‪25‬حبــة ) خمســة وعشــرين حبــة مــن احلبــوب احملظــورة بقصد‬\n‫الترويــج‪ .‬وذلــك لألدلــة والقرائــن التاليــة ‪ -1 :‬مــا جــاء بأقوالــه املنــوه عنها‬\n‫املدونــة علــى دفتــر التحقيــق املرفــق لفــه رقــم (‪ -2)7‬ومــا ورد مبحضــر‬\n\n\n                                                                                          ‫‪454‬‬\n\f      ‫القبــض والتفتيــش املنــوه عنــه املرفــق لفــة رقــم (‪ -3)1‬ومــا ورد بالتقريــر‬\n      ‫الكيميائــي الشــرعي املنــوه عنــه واملرفــق لفــة رقــم (‪ )8‬وبالبحــث عــن‬\n      ‫ســوابقه لــم يعثــر لــه علــى ســوابق مســجلة حتــى تاريخــه وحيــث إن‬\n      ‫مــا أقــدم عليــه املذكــور فعــل محــرم و معاقــب عليــه شــرع ًا ومجــرم‬\n      ‫ومعاقــب عليــه نظامــا مبوجــب نظــام مكافحــة املخــدرات واملؤثــرات‬\n      ‫العقليــة يف عقوباتــه األصليــة والتكميليــة لــذا أطلب‪-1:‬إثبــات إدانتــه‬\n      ‫مبــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة وفق ـ ًا للفقــرة األولــى‬\n      ‫مــن املــادة (‪ )38‬مــن ذات النظام‪-2.‬احلكــم بإبعــاده عــن البــاد اســتنادا‬\n      ‫للفقــرة (الثانيــة ) مــن املادة(‪)56‬مــن ذات النظــام ‪-3.‬احلكــم مبصــادرة‬\n      ‫جهــاز اجلــوال( مــن نــوع ‪ ......‬أســود اللــون بــه شــريحة ‪ ) .....‬املضبــوط‬\n      ‫مــع املدعــى عليــه واملســتخدم يف اجلرميــة والــذي يحمــل الرقــم املصنعــي‬\n      ‫(‪ ،)......‬وإيداعهــا بحســاب اإلدارة العامــة ملكافحــة املخــدرات حســب‬\n      ‫مــا نــص عليــه قــرار مجلــس الــوزراء رقــم (‪ )47‬وتاريــخ ‪ 1421/2/18‬هــ‪.‬‬\n      ‫وإلغــاء الشــريحة املضبوطــة بداخــل اجلــوال والتــي حتمــل الرقــم (‪)......‬‬\n      ‫وعــدم صرفهــا مــرة أخــرى ملــن أســاء اســتعمالها اســتنادا لتعميــم ســمو‬\n      ‫وزيــر الداخليــة رقــم (‪1/5/4/9798‬س) وتاريــخ (‪1428/2/10-9‬هــ)‬\n      ‫‪-4‬التشــديد عليــه لبيعــه احلبــوب احملظــورة ‪ ،‬اســتنادا لتعميــم صاحــب‬\n      ‫الســمو امللكــي وزيــر الداخليــة رقــم ‪ 8346‬يف ‪1427/2/8‬ه ـ خلطــورة‬\n      ‫مــادة الالمفيتامــن يف تدميــر مراكــز نهايــة األعصــاب املركزيــة باملخ‪.‬‬\n      ‫ا‬\n      ‫وبــاهلل التوفيــق (يتبــع) وبســؤال املدعــى عليــه عــن الدعــوى أجــاب قائـ ً‬\n      ‫صحيــح جميــع مــا نســبه إلــي املدعــي العــام جملــة وتفصيــا فقــد قمــت‬\n      ‫ببيــع مــا عــدده (‪25‬حبــة ) خمســة وعشــرين حبــة مــن احلبــوب احملظــورة‬\n      ‫بقصــد االجتــار مببلــغ ســبعمائة وخمســن ريــال علــى صفــة مــا ورد يف‬\n\n\n‫‪455‬‬\n\f‫الدعــوى واســتعملت الهاتــف اجلــوال يف عمليــة الترويــج وقــد اســتلمتها‬\n‫مــن شــخص حبشــي ال اعرفــه طلــب منــي تســليمها إلــى املشــتري وأنــا‬\n‫نــادم وأطلــب مســامحتي هكــذا أجــاب وقــد جــرى االطــاع علــى‬\n‫التقريــر الكيميائــي الشــرعي رقــم(‪/......‬س ‪2‬لعــام ‪ )......‬لعــام ‪......‬‬\n‫املتضمــن احتــواء عينــة احلبــوب املروجــة لإلمفيتامــن احملظــور كمــا‬\n‫جــرى االطــاع علــى جميــع مرفقــات املعاملــة فبنــاء علــى مــا تقــدم مــن‬\n‫الدعــوى واإلجابــة ومبــا أن املدعــى عليــه صــادق علــى صحــة جميــع مــا‬\n‫نســبه إليــه املدعــي العــام ومبــا أن مــا صــدر مــن املدعــى عليــه مــن احملــرم‬\n‫شــرع ًا ملــا يف احلبــوب احملظــورة مــن الضــرر واخلطــر علــى البــاد والعبــاد‬\n‫وعلــى مــن صــدر منــه قــال تعالــى ‪ « :‬وال تقتلــوا أنفســكم» وقــال « وال‬\n‫تفســدوا يف األرض بعــد إصالحهــا » ممــا يســتوجب اســتحقاق املدعــى‬\n‫عليــه للعقوبــة الــواردة يف املــادة الثامنــة والثالثــن مــن نظــام مكافحــة‬\n‫املخــدرات واملــادة السادســة واخلمســن ومبــا أن املدعــى عليــه ظهــر‬\n‫عليــه النــدم وأنــه ال ســوابق لــه ولقناعــة احملكمــة بظروفــه االجتماعيــة‬\n‫ولقلــة كميــة املخــدرات ولكونــه أجنبــي وال فائــدة مــن طــول بقائــه‬\n‫يف الســجن ممــا يتوجــه أن تكــون العقوبــة بالنســبة للســجن أقــل مــن‬\n‫العقوبــة الــواردة يف املــادة الثامنــة والثالثــن وإعمــا ًال للمــادة الســتني‬\n‫أيض ـ ًا لقناعــة احملكمــة باألســباب املوجبــة للتخفيــف حســب مــا نــوه‬\n‫عنــه ومبــا أنــه يشــرع للحاكــم أن يعــزر باملــال ممــا يســتوجب مصــادرة‬\n‫الهاتــف اجلــوال املنــوه عنــه متشــيا مــع املــادة الثالثــة واخلمســن لــذا كلــه‬\n‫وألجــل احلــق العــام حكمــت علــى املدعــى عليــه مبــا أفهــم بــه وهــو أو ًال ‪:‬‬\n‫ثبــت لــدي إدانــة املدعــى عليــه ببيــع مــا عــدده (‪25‬حبــة ) خمســة وعشــرين‬\n‫حبــة مــن احلبــوب الالمفيثامــن احملظــورة بقصــد الترويــج ثانيـاً‪ :‬أن يعــزر‬\n\n\n                                                                                         ‫‪456‬‬\n\f      ‫لقــاء ذلــك بــأن يســجن مــدة ســنة مــن تاريــخ إيقافــه علــى ذمــة القضيــة‬\n      ‫وأن يجلــد أربعمائــة جلــدة مفرقــة علــى ثمــان دفعــات كل دفعــة خمســون‬\n      ‫جلــدة بــن كل مــرة واألخــرى ال يقــل عــن أســبوع وأن يلــزم بدفــع أربعــة‬\n      ‫آالف ريــال تدفــع خلزينــة الدولــة وهــذا كلــه متشــي ًا مــع مقتضــى املــادة‬\n      ‫الثامنــة والثالثــن واملــادة الســتني مــن نظــام مكافحــة املخــدرات ثالثـاً‪:‬‬\n      ‫إبعــاده عــن البــاد بعــد انتهــاء محكوميتــه وهــذا حســب مقتضــى املــادة‬\n      ‫السادســة واخلمســن الفقــرة الثانيــة رابعــا‪ :‬أن يصــادر اجلــوال املنــوه عنــه‬\n      ‫املســتخدم يف عمليــة الترويــج وذلــك ببيعــه وإدخــال ثمنــه خزينــة الدولــة‬\n      ‫حســب املــادة الثالثــة واخلمســن وتعميــم وزيــر الداخليــة رقــم ‪ 9798‬يف‬\n      ‫‪1428/2/10-9‬ه ـ وإلغــاء الشــريحة املضبوطــة بداخــل اجلــوال والتــي‬\n      ‫حتمــل الرقــم(‪ )......‬وعــدم صرفهــا مــرة أخــرى ملــن أســاء اســتعمالها‬\n      ‫اســتنادا لتعميــم ســمو وزيــر الداخليــة رقــم (‪1/5/4/9798‬س) وتاريــخ‬\n      ‫(‪1428/2/10-9‬هــ) وبعــرض احلكــم علــى املدعــى عليــه قنــع بــه كمــا‬\n      ‫قــرر املدعــي العــام املعارضــة وطلــب رفعهــا حملكمــة االســتئناف بــدون‬\n      ‫تقــدمي الئحــة اعتراضيــة مكتفيــا مبــا جــاء يف أوراق املعاملــة هــذا وقــد‬\n      ‫جــرى توجيــه املدعــى عليــه بــأن عليــه البعــد عــن املخــدرات ولــزوم التوبــة‬\n      ‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                    ‫وســلم ‪ .‬حــرر يف ‪......‬‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى لتدقيــق‬\n      ‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة ‪ ......‬علــى املعاملــة‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة ‪ ......‬برقــم ‪ ......‬وتاريــخ‬\n      ‫‪ ......‬املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي باحملكمــة‬\n      ‫الشــيخ‪ ...... /‬برقــم ‪ ......‬وتاريــخ ‪ ......‬اخلــاص بدعــوى املدعــي العــام ضــد‬\n\n\n‫‪457‬‬\n\f‫‪( ...... /‬مينــي اجلنســية) يف قضيــة (مخــدرات) علــى الصفــة املوضحــة يف‬\n‫القــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه وبدراســة‬\n‫القــرار وصــورة ضبطــه وأوراق املعاملــة تقــررت املوافقــة علــى احلكــم ‪.‬‬\n      ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                ‫‪458‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":452,"source_page_end":458,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"6c79e5bce689055c987151ae97766dbe5f671599e62b39a6afc5b2601f09c0b6","normalized_text_hash":"883be2c006b7316895d664e2f8185d05d8a121e4791089a0fad53a34614c84a6","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p452-3430461"},{"id":"1d6fb376-d29f-5646-8434-f2a7b9235fc8","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج قطعة حشيش -ترويج حبوب محظورة -تعاطي احلشيش املخدر -إقرار -إقامة حد املسكر على متعاطي احلشيش- التعزير بالسجن واجللد والغرامة واملنع من السفر واملصادرة.","document_number":"34246874","case_number":"3457966","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/20","year":"1434","subject":"مخدرات -ترويج قطعة حشيش -ترويج حبوب محظورة -تعاطي احلشيش املخدر -إقرار -إقامة حد املسكر على متعاطي احلشيش- التعزير بالسجن واجللد والغرامة واملنع من السفر واملصادرة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك‪ 34246874:‬تاريخه ‪1434/6/20 :‬هـ‬\n                           ‫رقم الدعوى ‪3457966:‬‬\n                   ‫رقم قرار التصديق من محكمة‬\n      ‫االستئناف‪ 34350592:‬تاريخه‪1434/11/05 :‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬ترويــج قطعــة حشــيش ‪ -‬ترويــج حبــوب محظــورة ‪ -‬تعاطــي‬\n      ‫احلشــيش املخــدر‪ -‬إقــرار ‪ -‬إقامــة حــد املســكر علــى متعاطي احلشــيش‪-‬‬\n            ‫التعزيــر بالســجن واجللــد والغرامــة واملنــع مــن الســفر واملصــادرة‪.‬‬\n\n\n\n\n                                                   ‫‪ -1‬قاعدة املرء مؤاخذ بإقراره‪.‬‬\n                                                         ‫‪ -2‬قاعدة ال عذر ملن أقر‪.‬‬\n      ‫‪ -3‬قولــه تعالــى (يــا أيهــا الذيــن آمنــوا إمنــا اخلمــر وامليســر واألنصــاب‬\n            ‫واألزالم رجــس مــن عمــل الشــيطان فاجتنبــوه لعلكــم تفلحــون)‪.‬‬\n      ‫‪ -4‬قولــه صلــى اهلل عليــه وســلم (كل مســكر خمــر وكل خمــر حــرام)‬\n                                                                             ‫رواه مسلم‪.‬‬\n      ‫‪ -5‬قــال املــرداوي يف اإلنصــاف (‪( :)438/8‬وأبــو العبــاس يــرى أن‬\n      ‫حكمهــا حكــم الشــراب املســكر يف إيجــاب احلــد وهــو الصحيــح إن‬\n                                                                              ‫أســكر)‪.‬‬\n      ‫‪ -6‬قــال شــيخ اإلســام يف الفتــاوى (‪( :)198/34‬وكذلــك احلشيشــة‬\n      ‫املســكرة يجــب فيهــا احلــد ومــن ظــن أن احلشيشــة ال تســكر وإمنــا‬\n      ‫تغيــب العقــل بــا لــذة فلــم يعــرف حقيقــة أمرهــا)‪ .‬وقــال يف موضــع آخــر‬\n      ‫(الصحيــح أن احلشيشــة مســكرة كالشــرب)‪ .‬الفتــاوى (‪.)214/34‬‬\n      ‫‪ -7‬قــال ابــن حجــر‪( :‬واســتدل مبطلــق قولــه صلــى اهلل عليــه وســلم (كل‬\n      ‫مســكر حــرام) علــى حتــرمي مــا يســكر ولــو لــم يكــن شــراب ًا فيدخــل‬\n‫‪459‬‬\n\f   ‫يف ذلــك احلشيشــة وغيرهــا وقــد جــزم النــووي وغيــره بأنهــا مســكرة)‪.‬‬\n‫‪ -8‬وألن الصحابــة رضــي اهلل عنهــم ملــا تشــاوروا يف عهــد عمر رضي اهلل‬\n‫عنــه حــن أكثــر النــاس مــن شــرب اخلمــر قــال عبدالرحمــن بــن عــوف‬\n     ‫رضــي اهلل عنــه‪( :‬أخــف احلــدود ثمانــون فوافــق علــى ذلــك الصحابــة)‪.‬‬\n‫‪ -9‬قــرار هيئــة كبــار العلماء رقــم (‪ )53‬وتاريخ ‪1397/4/4‬هـ املتضمن‪:‬‬\n‫بــأن عقوبــة شــارب اخلمــر احلــد ال التعزيــر باإلجمــاع‪ ،‬كمــا قــرر أنــه‬\n                                                                 ‫ثمانــون جلــدة‪.‬‬\n‫‪ -10‬يســوغ اجلمــع بــن احلــد والتعزيــر إذا وجــدت جنايتــن ملــا روى أحمــد‬\n‫بإســناده أن علي ـ ًا أتــى بالنجاشــي قــد شــرب خمــر ًا يف رمضــان فجلــده‬\n‫ثمانــون احلــد وعشــرين ســوط ًا لفطــرة يف رمضــان‪ .‬وأخرجــه أيض ـ ًا‬\n     ‫عبدالــرزاق وابــن أبــي شــيبة البيهقــي‪ .‬كشــاف القنــاع (‪.)112/14‬‬\n‫‪ -11‬الفقــرة (‪ )1‬مــن املــادة (‪ )38‬مــن نظــام مكافحــة املخــدرات‬\n                                                        ‫واملؤثــرات العقليــة ‪..‬‬\n‫‪ -12‬الفقــرة (‪ )1‬مــن املــادة (‪ )60‬مــن نظــام مكافحــة املخــدرات‬\n                                                         ‫واملؤثــرات العقليــة ‪.‬‬\n‫‪ -13‬الفقــرة (‪ )1‬مــن املــادة (‪ )62‬مــن نظــام مكافحــة املخــدرات‬\n                                                         ‫واملؤثــرات العقليــة ‪.‬‬\n‫‪ -14‬الفقــرة (‪ )1‬مــن املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات‬\n                                                         ‫واملؤثــرات العقليــة ‪.‬‬\n                                                     ‫‪ -15‬قاعدة‪ :‬رفع الضرر‪.‬‬\n     ‫‪ -16‬تعميم سمو وزير الداخلية رقم (‪ )9798‬وتاريخ ‪1428/2/10‬هـ‪.‬‬\n\n\n\n\n                                                                                    ‫‪460‬‬\n\f      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بترويــج احلشــيش املخــدر وعــدد‬\n      ‫مــن احلبــوب احملظــورة بقصــد الترويــج وتعاطــي احلشــيش املخــدر‪ .‬حيــث‬\n      ‫وردت معلومــات ملكافحــة املخــدرات تفيــد بــأن املدعــى عليــه لــه نشــاط‬\n      ‫يف ترويــج احلشــيش املخــدر واحلبــوب احملظــورة ومت التنســيق مــع املصــدر‬\n      ‫للقبــض علــى املدعــى عليــه متلبس ـ ًا ومتــت عمليــة االســتالم والتســليم‬\n      ‫وطلــب املدعــي العــام إثبــات مــا أســند للمدعــى عليــه‪ ،‬أقــر املدعــى عليــه‬\n      ‫مبــا نســب إليــه وأثبــت التقريــر الكيمائــي الشــرعي إيجابيــة العينــة‬\n      ‫املرســلة ملــادة احلشــيش املخــدرة ومــادة اإلمفيتامــن ‪ ،‬بنــاء علــى مــا‬\n      ‫ســبق حكمــت احملكمــة بإقامــة حــد املســكر وتعزيــر املدعــى عليــه‬\n      ‫بالســجن واجللــد والغرامــة واملنــع مــن الســفر ومصــادرة اجلــوال وإلغــاء‬\n                           ‫وصــدق احلكــم مــن محكمــة االســتئناف‪.‬‬       ‫الشــريحة ُ‬\n\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلدي أنا‬\n      ‫‪ .........‬القاضي باحملكمة اجلزائية بالدمام ففي يوم السبت املوافق‬\n      ‫‪1434/05/25‬ه ـ افتتحــت اجللســة الســاعة التاســعة صباحـ ًا بنــاء علــى‬\n      ‫املعاملــة احملالــة إلينــا مــن فضيلــة رئيــس احملكمــة اجلزائيــة بالدمــام‬\n      ‫برقــم ‪ ..............‬وتاريــخ ‪ 1434 /02 /04‬ه ـ واملقيــدة بــوارد مكتبنــا‬\n      ‫برقــم ‪ ..............‬واملتعلقــة بدعــوى املدعــي العــام ضــد ‪ .....‬املدعــى عليــه‬\n      ‫وفيهــا حضــر املدعــي العــام ‪ ......‬وادعــى علــى احلاضــر معــه ‪ .....‬املدعــى‬\n      ‫عليــه ســعودي اجلنســية بالبطاقــة رقــم ‪ .....‬قائــا يف دعــواه باالطــاع‬\n‫‪461‬‬\n\f‫علــى محاضــر البــاغ واالتصــال واالنتقــال والقبــض والتفتيــش املعــدة‬\n‫مــن قبــل رجــال مكافحــة املخــدرات تبــن أنــه يف يــوم األربعــاء املوافــق‬\n‫‪1433/12/29‬ه ـ وردتهــم معلومــات مــن أحــد مصادرهــم الســرية والتــي‬\n‫تفيــد بوجــود شــخص يدعــى ‪ .....‬يســكن القطيــف بالدخــل احملــدود ولــه‬\n‫نشــاط يف ترويــج احلشــيش املخــدر واحلبــوب احملظــورة ‪ ،‬واســتعد مصــدر‬\n‫املعلومــة لإلطاحــة باملذكــور متلبســا بجرمــه املشــهود‪ ،‬فجــرى متكينــه‬\n‫مــن االتصــال علــى جــوال املتهــم (‪ )....‬املذكــور أعــاه رقــم (‪).............‬‬\n‫رقمــه املصنعــي (‪ )...............‬وطلــب منــه حشــيش مخــدر مببلــغ (‪)200‬‬\n‫مئتــي ريــال‪ ،‬فوافــق (‪ ).....‬املذكــور علــى ذلــك وذكــر أنــه ســوف يذهــب‬\n‫إلــى البحريــن عنــد الســاعة العاشــرة والنصــف مســاء‪ ،‬واتفقــا علــى ان‬\n‫يتقابــا علــى طريــق الظهــران اجلبيــل‪ ،‬وحــدد مصــدر املعلومــة مــكان‬\n‫االســتالم والتســليم محطــة بنزيــن ‪ ،‬وكانــت املكاملــة علــى مســمع مــن‬\n‫أفــراد الفرقــة القابضــة ‪ ،‬فتــم تفتيــش املصــدر وســيارته تفتيشــا دقيقــا‬\n‫وتزويــده مببلــغ مرقــم وقــدره (‪ )200‬مائتــي ريــال و تكليــف أحــد أفــراد‬\n‫الفرقــة القابضــة مبرافقتــه ‪ ،‬وحتــرك املصــدر ومرافقــه حتــت أنظــار‬\n‫أفــراد الفرقــة القابضــة حتــى توقفــا باملوقــع احملــدد‪ ،‬وحضــرت باملوقــع‬\n‫ســيارة نــوع ‪ 2001 ....‬كحليــة اللــون حتمــل اللوحــة رقــم (؟ ‪ -)....‬جــرى‬\n‫رد الســيارة ‪ -‬وبهــا ثالثــة أشــخاص‪ ،‬وتوقفــوا بجانــب املصــدر ومرافقــه‬\n‫‪ ،‬ونــزل قائــد الســيارة (‪ )...‬املذكــور وتقابــل مــع املصــدر وقــام (‪)...‬‬\n‫املذكــور بتســليم املصــدر قطعــة تــزن (‪ )11,2‬إحــدى عشــر جرام ـ ًا‬\n‫واثنــن مــن العشــرة مــن اجلــرام اثبــت التقريــر الكيمــاوي الشــرعي‬\n‫رقــم (‪ ..‬ك ش) وتاريــخ ‪1734/1/7‬ه ـ ايجابيــة عينتهــا ملــادة احلشــيش‬\n‫املخــدر املــدرج يف اجلــدول ( ‪ )1‬فئــة (أ) مــن نظــام مكافحــة املخــدرات‬\n\n\n                                                                                     ‫‪462‬‬\n\f      ‫واملؤثــرات العقليــة ‪ ،‬واســتلم قيمتهــا وقدرهــا (‪ )200‬مائتــا ريــال‪،‬‬\n      ‫كمــا قــام (‪ )...‬املذكــور بإهــداء املصــدر عــدد (‪ )3‬ثــاث حبــات أثبــت‬\n      ‫التقريــر الكيمــاوي الشــرعي املشــار اليــه ايجابيتهــا جميعــا كال علــى‬\n      ‫حــده ملــادة االمفيتامــن املنبهــة احملظــورة املــدرج يف اجلــدول ( ‪ ) 2‬فئــة‬\n      ‫(ب) مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ‪ ،‬وغــادر(‪)...‬‬\n      ‫ومرافقــاه املوقــع وأعطيــت اإلشــارة املتفــق عليهــا إلمتــام عمليــة االســتالم‬\n      ‫والتســليم ‪ ،‬فتمــت متابعتــه حتــى ســلك طريــق اجلســر ‪ ،‬فجــرى التنســيق‬\n      ‫مــع الدوريــات األمنيــة مبنفــذ اجلســر و وضــع نقطــة حتكــم قبــل وصولــه‬\n      ‫‪ ،‬ومت اســتيقافه ومرافقيــه واتضــح أن قائــد الســيارة (‪ )....‬املذكــور ‪،‬‬\n      ‫وبتفتيشــه لــم يعثــر علــى أي شــيء مــن املمنوعــات‪ ،‬و عثــر علــى املبلــغ‬\n      ‫املرقــم كامــا بحــوزة املذكــور بجيــب بنطالــه اجلانبــي‪ ،‬واتضــح أن‬\n      ‫مرافقــه األمامــي (‪ ، ).....‬وبتفتيشــه لــم يعثــر بحوزتــه علــى أي شــيء‬\n      ‫مــن املمنوعــات ‪ ،‬وكانــت تنبعــث مــن جوفــه رائحــة اخلمــر املســكر‪،‬‬\n      ‫واتضــح أن مرافقهــم الثالــث (‪ ، )....‬وبتفتيشــه لــم يعثــر بحوزتــه علــى أي‬\n      ‫ممنوعــات‪ ، ،‬وبتفتيــش الســيارة عثــر حتــت مقعد الراكب على كيس‬\n      ‫نايلــون وجــد بداخلــه عــدد (‪ )23‬ثالثــة وعشــرين حبــة اثبــت التقريــر‬\n      ‫الكيمــاوي الشــرعي الســابق ايجابيــة عينتهــا ملــادة االمفيتامــن املنبهــة‬\n      ‫احملظــورة (اعتــرف ‪ /‬بحيازتهــا) ‪( ،‬فــرزت أوراق مســتقلة للمتهمــن‬\n                                  ‫(‪ ).....‬و (‪ )......‬إلقامــة الدعــوى مبقــر اقامتهمــا‪.‬‬\n      ‫وباســتجواب املتهــم (‪ ).......‬اقــر بصحــة واقعــة القبــض ‪ ،‬وأفــاد إنــه يف‬\n      ‫يــوم األربعــاء املوافــق ‪ 1433/12/29‬ه ـ اتصــل بــه املصــدر وطلــب منــه‬\n      ‫قطعــة حشــيش مخــدر مببلــغ مئتــي ريــال‪ ،‬فوافــق وأخبــره أنــه متجــه‬\n      ‫إلــى البحريــن‪ ،‬واتفقــا علــى أن يتقابــا مبحطــة بنزيــن علــى طريــق‬\n\n\n‫‪463‬‬\n\f‫الظهــران‪ ،‬فحضــر للموقــع وقابــل املصــدر وكان برفقتــه شــخص وقــام‬\n‫بتســليم املصــدر قطعــة مــن احلشــيش املخــدر‪ ،‬واســتلم منــه مبلــغ مئتــي‬\n‫ريــال‪ ،‬واجتــه إلــى جســر امللــك فهــد‪ ،‬فتــم إيقافــه مــن قبــل نقطــة تفتيــش‬\n    ‫والقبــض عليــه ‪ ،‬مضيف ـ ًا أنــه قــام بتســليم املصــدر (‪ )3‬ثــاث حبــات‬\n‫مــن احلبــوب املنبهــة احملظــورة محتســبا احلشــيش املخــدر مببلــغ مئــة‬\n‫وخمســن ريــاال‪ ،‬والثــاث حبــات بخمســن ريــاال‪ ،‬فــكان إجمالــي‬\n‫املبلــغ مئتــي ريــال وانــه ليــس لرفيقيــه عالقــة أو علــم مبــا قــام بــه مــن‬\n‫ترويــج للحشــيش املخــدر واحلبــوب املنبهــة ‪ ،‬كمــا اقــر بتعاطــي احلشــيش‬\n‫املخــدر منــذ شــهر وآخــر مــرة كانــت قبــل القبــض عليــه بيومــن ‪ ،‬نافيــا‬\n                ‫عالقتــه او علمــه باحلبــوب املنبهــة املضبوطــة يف الســيارة ‪.‬‬\n                        ‫وقد انتهى التحقيق إلى اتهام املدعى عليه باالتي‪:‬‬\n‫‪ -1‬بيــع قطعــة تــزن (‪ )11,2‬إحــدى عشــر جرام ـ ًا واثنــان مــن العشــرة‬\n‫مــن اجلــرام مــن احلشــيش املخــدر ‪ ،‬وعــدد (‪ )3‬ثــاث حبــات مــن حبــوب‬\n                            ‫االمفيتامــن املنبهــة احملظــورة بقصــد االجتــار ‪.‬‬\n                                                  ‫‪ -2‬تعاطي احلشيش املخدر ‪.‬‬\n                                               ‫وذلك لألدلة والقرائن التالية ‪:‬‬\n‫‪ -1‬اعترافــه حتقيقــا بصحــة واقعــة القبــض املنــوه عنــه املرفــق علــى‬\n                                                        ‫اللفــات رقــم (‪)25-22‬‬\n‫‪ -2‬محاضــر البــاغ واالتصــال والقبــض والتفتيــش املنــوه عنهــا املدونــة‬\n‫علــى الصفحــات رقــم (‪ )14-12 ، 4 ، 2‬مــن ملــف التحقيــق املرفــق لفــة‬\n                                                                              ‫(‪.)1‬‬\n‫‪ -3‬التقريــر الكيمــاوي الشــرعي املنــوه عنــه املرفــق علــى اللفــة رقــم‬\n                                                                             ‫(‪)32‬‬\n\n\n                                                                                       ‫‪464‬‬\n\f      ‫وحيــث إن مــا أقــدم عليــه املذكــور ‪ ،‬وهــو بكامــل أهليتــه املعتبــرة‬\n      ‫شــرع ًا ‪ ،‬فعــل محــرم ومعاقــب عليــه شــرع ًا ونظام ـ ًا أطلــب إثبــات مــا‬\n      ‫اســند اليــه وفــق الفقــرة رقــم(‪ )2‬مــن املــادة رقــم(‪ )3‬مــن نظــام مكافحــة‬\n                         ‫املخــدرات واملؤثــرات العقليــة واحلكــم عليــه مبــا يلــي‪:‬‬\n      ‫‪ .1‬بعقوبــة الســجن واجللــد والغرامــة الــواردة بالفقــرة رقــم (‪ )1‬مــن‬\n      ‫املــادة رقــم(‪ )38‬مــن النظــام‪ ،‬ووفــق الفقــرة رقــم (‪ )1‬مــن املــادة رقــم‬\n      ‫(‪ )62‬مــن النظــام بتطبيــق العقوبــة األشــد ‪ ،‬و التشــديد عليــه كــون‬\n      ‫املــادة املروجــة حبــوب منبهــة وفــق الفقــرة (‪/2‬ج) مــن املــادة رقــم(‪)38‬‬\n      ‫مــن النظــام‪ ،‬و اســتنادا لبرقيــة صاحــب الســمو امللكــي وزيــر الداخليــة‬\n                                ‫رقــم(‪2/8346/5/1‬ش) وتاريــخ ‪1427/2/8‬ه ـ ‪.‬‬\n          ‫‪.2‬منعه من السفر وفق الفقرة رقم(‪ )1‬من املادة رقم(‪ )56‬من النظام‪.‬‬\n      ‫‪.3‬مصــادرة هاتــف (املدعــى عليــه) النقــال املســتخدم يف اجلرمية املوصوف‬\n      ‫بالوقائــع وفــق الفقــرة (‪ )1‬مــن املــادة رقم (‪ )53‬مــن النظام‪ ،‬وعدم صرف‬\n      ‫شــريحة الهاتــف لنفــس املدعــى عليــه وفقـ ًا لتعميــم وزيــر الداخليــة رقــم‬\n                                                   ‫(‪ )9798‬وتاريخ ‪1428/2/10-9‬هـ‪.‬‬\n      ‫مــا ذكــره املدعــي العــام مــن أننــي قمــت ببيــع قطعــة بلــغ وزنهــا (‪)11.2‬‬\n      ‫إحــدى عشــر جرامـ ًا واثنــن مــن العشــرة مــن اجلــرام مــن احلشــيش املخــدر‬\n      ‫وعــدد (‪ )3‬ثــاث حبــات مــن حبــوب االمفيتامــن املنبهــة واحملظــورة‬\n      ‫فصحيــح إال أننــي كنــت وقــت البيــع يف حالة ســكر ومــا ذكره املدعي‬\n      ‫العــام مــن أننــي أتعاطــى احلشــيش املخــدر فصحيــح هكــذا أجــاب ثــم‬\n      ‫جــرى ســؤال املدعــى عليــه عــن الرقــم (‪ )........................‬املذكــور يف‬\n      ‫ا هــذا هــو رقمــي وهــو الرقــم الــذي اتصــل علــي‬     ‫الدعــوى فأجــاب قائ ـ ً‬\n      ‫املصــدر لطلــب املخــدرات منــي هكــذا أجــاب وقــد جــرى اطالعــي علــى‬\n\n\n‫‪465‬‬\n\f‫أوراق املعاملــة كمــا جــرى اطالعــي علــى التقريــر الكيماوي الشــرعي‬\n‫رقــم ‪ ....‬ك ش وتاريــخ ‪1434/1/7‬ه ـ املرفــق باملعاملــة لفــة رقــم (‪)33‬‬\n‫واملتضمــن ثبــوت إيجابيــة عينــة القطعــة ملــادة احلشــيش املخــدر وثبــوت‬\n   ‫ال علــى حــده ملــادة اإلمفيتامــن ‪.‬‬\n                                       ‫إيجابيــة عينــة احلبــوب املضبوطــة ك ً‬\n‫كمــا جــرى اطالعــي علــى صحيفــة ســوابق املدعــى عليــه املرفقــة‬\n‫باملعاملــة لفــة رقــم (‪ )35‬املتضمنــة ســرقة محــات جتاريــة وســرقة‬\n‫مســاكن وفعــل فاحشــة اللــواط وبعرضهــا علــى املدعــى عليــه صــادق‬\n‫علــى صحتهــا فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ونظــرا ملــا‬\n‫قــرره الطرفــان ومــا مت رصــده وضبطــه أعــاه وبعــد االطــاع علــى أوراق‬\n‫املعاملــة ودراســتها ونظــرا ملصادقــة املدعــى عليــه بأنــه بــاع احلشــيش‬\n‫املخــدر واحلبــوب املنبهــة واحملظــورة واملــرء مؤاخــذ بإقــراره وال عــذر ملــن‬\n‫أقــر ونظــرا إلــى دفعــه بأنــه كان يف حالــة ســكر وقــت البيــع فهــذا غيــر‬\n‫مقبــول وذلــك أن الســكر الــذي يدعيــه املدعــى عليــه لــم يكــن مغلق ـ ًا‬\n‫للعقــل وال مغطيـ ًا لــه بدليــل تذكــر واقعــة املدعــى عليــه اتصــال املصــدر‬\n‫عليــه وتذكــره لواقعــة بيعــه للمخــدرات ونظــرا إلــى أن مــا قــام به املدعى‬\n‫عليــه هــو محــرم شــرعا ومجــرم نظامــا ونظــرا إلــى أن تعاطــي احلشــيش‬\n‫املخــدر يــؤدي إلــى اإلســكار‪ ،‬وقــد نــص أهــل العلــم علــى إقامــة احلــد‬\n‫علــى متنــاول احلشــيش كمــا ذكــر املــرداوي يف اإلنصــاف يف (‪)438/8‬‬\n‫حيــث قــال ‪ »:‬وأبــو العبــاس يــرى أن حكمهــا حكــم الشــراب املســكر‬\n‫يف إيجــاب احلــد وهــو الصحيــح إن أســكرت أو كثيرهــا وإال حرمــت‬\n‫وعزر فقط» وقال شــيخ اإلســام ‪ « :‬وكذلك احلشيشــة املســكرة يجب‬\n‫فيهــا احلــد ومــن ظــن أن احلشيشــة ال تســكر وإمنــا تغيــب العقــل بــا لــذة‬\n‫فلــم يعــرف حقيقــة أمرهــا «(‪ ،)198/34‬وقــال‪ »:‬الصحيــح أن احلشيشــة‬\n\n\n                                                                                      ‫‪466‬‬\n\f      ‫مســكرة كالشــراب « الفتــاوى (‪ )214/34‬قــال ابــن حجــر ‪»:‬واســتدل‬\n      ‫مبطلــق قولــه صلــى اهلل عليــه وســلم ‪( :‬كل مســكر حــرام) علــى حتــرمي‬\n      ‫مــا يســكر ولــو لــم يكــن شــرابا فيدخــل يف ذلــك احلشيشــة وغيرهــا‬\n             ‫وقــد جــزم النــووي وغيــره بأنهــا مســكرة « فتــح البــاري (‪)45/10‬‬\n      ‫واهلل تعالــى يقــول‪ ( :‬يــا أيهــا الذيــن آمنــوا إمنــا اخلمــر وامليســر واألنصــاب‬\n      ‫واألزالم رجــس مــن عمــل الشــيطان فاجتنبــوه لعلكــم تفلحــون ) ولقولــه‬\n      ‫صلــى اهلل عليــه وســلم‪ ( :‬كل مســكر خمــر وكل خمــر حــرام )رواه‬\n      ‫مســلم «وألن الصحابة ـ رضي اهلل عنهم ملا تشــاوروا يف عهد عمر رضي‬\n      ‫اهلل عنــه حــن أكثــر النــاس مــن شــربه‪ ،‬قــال عبــد الرحمــن بــن عــوف‬\n      ‫رضــي اهلل عنــه‪ :‬أخــف احلــدود ثمانــون فوافــق علــى ذلــك الصحابــة» أ‪.‬ه ـ‬\n                                                              ‫الشــرح املمتــع (‪. )293/14‬‬\n      ‫واســتناد ًا لقــرار هيئــة كبــار العلمــاء رقــم ‪ 53‬وتاريــخ ‪1397/4/4‬ه ـ‬\n      ‫والــذي تضمــن بــأن عقوبــة شــارب اخلمــر احلــد ال التعزيــر باإلجمــاع كمــا‬\n                                                            ‫قــرر أنــه ثمانــون جلــدة‪ .‬أ‪.‬ه ـ‬\n      ‫وألنــه يســوغ اجلمــع بــن احلــد والتعزيــر إذا وجــد جنايتــن ملــا روى أحمــد‬\n      ‫بإســناده أن علي ـ ًا أتــي بالنجاشــي قــد شــرب خمــر ًا يف رمضــان فجلــده‬\n      ‫ثمانــن احلــد وعشــرين ســوط ًا لفطــره يف رمضــان وأخرجــه أيض ـ ًا‬\n           ‫عبدالــرزاق وابــن أبــي شــيبة والبيهقــي (كشــاف القنــاع ‪)112/14‬‬\n      ‫وبنــاء علــى الفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )38‬مــن نظــام مكافحــة‬\n                                                       ‫املخــدرات واملؤثــرات العقليــة ‪.‬‬\n      ‫ونظرا إلى أن ســوابق املدعى عليه ليســت من جنس املخدرات الســوابق‬\n      ‫ونظــرا لقلــة الكميــة ونظــرا ملــا ظهــر لــي مــن أخــاق املدعــى عليــه‬\n      ‫وبنــاء علــى الفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )60‬مــن نظــام مكافحــة‬\n\n\n‫‪467‬‬\n\f‫املخــدرات واملؤثــرات العقليــة والتــي تقتضــي النــزول عــن احلــد األدنــى‬\n     ‫مــن عقوبــة الســجن املنصــوص عليهــا يف املــادة (الثامنــة والثالثــن)‬\n                                                                      ‫ولكل ما سبق ‪:‬‬\n‫(أوالً)‪:‬ثبــت لــدي إدانــة املدعــى عليــه مبــا نســب إليــه مــن بيــع قطعــة بلــغ‬\n‫وزنهــا (‪ )11.2‬احــدى عشــرة جرامــا واثنــن مــن العشــرة مــن اجلــرام مــن‬\n‫احلشــيش املخــدر وبيــع عــدد (‪ )3‬حبــات مــن حبــوب االمفيتامــن املنبهــة‬\n‫واحملظــورة بقصــد الترويــج وبذلــك حكمــت ‪ ،‬وحكمــت علــى املدعــى‬\n                                                         ‫عليــه لقــاء ذلــك مبــا يلــي ‪:‬‬\n‫(‪ )1‬حكمــت علــى املدعــى عليــه بســجنه ســنتني ونصــف يحتســب‬\n‫منهــا مــا أمضــاه موقوفــا يف هــذه القضيــة وذلــك وفقــا للفقــرة رقــم (‪)1‬‬\n‫مــن املــادة رقــم (‪ )38‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n‫ووفق ـ ًا للفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )60‬مــن نظــام مكافحــة‬\n                                                 ‫املخــدرات واملؤثــرات العقليــة ‪.‬‬\n              ‫(‪ )2‬حكمت على املدعى عليه بجلده مائة وخمسون جلدة‬\n‫علــى دفعــات كل دفعــة خمســون جلــدة بــن كل دفعــة والتــي تليهــا‬\n                                                                            ‫عشــرة أيــام‬\n‫علــى أن يكــون جلــد احلــد قبــل أول دفعــة يف جلــد التعزيــر بخمســة عشــر‬\n                                                                                     ‫يوما‬\n‫وذلــك وفقــا للفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )38‬مــن نظــام مكافحــة‬\n                                                   ‫املخــدرات واملؤثــرات العقليــة‪.‬‬\n‫(‪ )3‬حكمــت علــى املدعــى عليــه بدفــع غرامــة ماليــة وقدرهــا ألــف‬\n                                                                     ‫وخمســمائة ريــال‬\n‫وذلــك وفقــا للفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )38‬مــن نظــام مكافحــة‬\n\n\n                                                                                             ‫‪468‬‬\n\f                                                     ‫املخــدرات واملؤثــرات العقليــة ‪.‬‬\n      ‫(‪)4‬حكمــت علــى املدعــى عليــه مبنعــه مــن الســفر إلــى خــارج اململكــة‬\n      ‫بعــد انتهــاء عقوبــة الســجن ملــدة ســنتني ونصــف وفقــا للفقــرة رقــم (‪)1‬‬\n      ‫مــن املــادة رقــم (‪ )56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ‪.‬‬\n      ‫(‪ )5‬حكمــت علــى املدعــى عليــه مبصــادرة هاتفــه اجلــوال املســتخدم يف‬\n      ‫الترويــج واملذكــور يف الئحــة دعــوى املدعــي العــام وذلــك وفقــا للفقــرة‬\n      ‫رقــم (‪ )1‬مــن املــادة رقــم (‪ )53‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                              ‫العقليــة‪.‬‬\n      ‫(‪ )6‬حكمــت علــى املدعــى عليــه بإســقاط شــريحته املســتخدمة يف‬\n      ‫الترويــج واملذكــورة يف الئحــة دعــوى املدعــي العــام وعــدم صرفهــا‬\n      ‫للمتهــم نفســه وذلــك بنــاء علــى تعميــم ســمو وزيــر الداخليــة رقــم ( ‪)9798‬‬\n                                                         ‫وتاريــخ ‪1428/2/10-9‬هــ‪.‬‬\n      ‫(ثاني ـاً)‪ :‬ثبــت لــدي إدانــة املدعــى عليــه مبــا نســب إليــه مــن تعاطيــه‬\n                                                                  ‫للحشــيش املخــدر‬\n      ‫وبذلــك حكمــت ‪ ،‬وحكمــت علــى املدعــى عليــه لقــاء ذلــك حــدا بجلده‬\n           ‫ثمانــن جلــدة دفعــة واحــدة يف مــكان عــام إقامــة حلــد املســكر عليه ‪.‬‬\n      ‫وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه قناعتــه باحلكــم‬\n      ‫وقــرر املدعــي العــام االعتــراض علــى احلكــم بالئحــة اعتراضيــة فأجبتــه‬\n      ‫لطلبــه وأفهمــت املدعــي العــام بــأن عليهــم مراجعــة احملكمــة يف يــوم‬\n      ‫األربعــاء املوافــق ‪14 34 / 06 /14‬ه ـ الســتالم نســخة مــن احلكــم‬\n      ‫لتقــدمي الئحتــه االعتراضيــة خــال ثالثــن يومــا مــن تاريــخ االســتالم‬\n      ‫وإال ســقط حقــه يف طلــب االســتئناف وختمــت يف الســاعة العاشــرة‬\n      ‫والنصــف صباحــا وعلــى ذلــك جــرى التوقيــع وبــاهلل التوفيــق وصلــى اهلل‬\n                            ‫وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n‫‪469‬‬\n\f‫احلمــد هلل وحــده والصــاة والســام علــى مــن النبــي بعــده وبعــد ففــي‬\n‫هــذا اليــوم األربعــاء املوافــق ‪1434/07/12‬ه ـ افتتحــت اجللســة يف‬\n‫الســاعة العاشــرة صباحــا وفيهــا حضــر املدعــي العــام وجــرى تســليمه‬\n‫نســخة مصــورة مــن قــرار احلكــم وللمعلوميــة فقــد جــرى حتريــره‬\n‫وختمــت اجللســة يف الســاعة العاشــرة والنصــف صباح ـ ًا وعلــى ذلــك‬\n‫جــرى التوقيــع وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى‬\n                         ‫آلــه وصحبــه وســلم حــرر يف ‪1434 /07/ 12‬هــ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ففــي‬\n‫األحــد يــوم املوافــق ‪14 34/ 08/14‬ه ـ افتتحــت اجللســة الســاعة‬\n‫العاشــرة صباحــا وفيهــا قــد انتهــت املــدة املنصــوص عليهــا يف املــادة‬\n‫الرابعــة والتســعني بعــد املائــة مــن نظــام اإلجــراءات اجلزائيــة ولــم يتقــدم‬\n‫املدعــي العــام بالئحتــه االعتراضيــة خــال هــذه املــدة لــذا قــررت رفــع‬\n‫كامــل املعاملــة حملكمــة االســتئناف وفقــا ملــا نصــت عليــه اخلامســة‬\n‫والتســعون بعــد املائــة مــن نظــام اإلجــراءات اجلزائيــة وللمعلوميــة فقــد‬\n‫جــرى حتريــره وختمــت يف الســاعة العاشــرة والنصــف صباحــا وعلــى‬\n‫ذلــك جــرى التوقيــع وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد‬\n                   ‫وعلــى آلــه وصحبــه وســلم حــرر يف ‪14 34 /08/14‬ه ـ ‪.‬‬\n‫احلمــد اهلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ففــي‬\n‫يــوم الثالثــاء املوافــق ‪14 34 / 11 /25‬ه ـ افتتحــت اجللســة الســاعة‬\n‫احلاديــة عشــرة وخمــس وأربعــون دقيقــة وفيهــا عــادت املعاملــة مــن‬\n‫محكمــة االســتئناف باملنطقــة الشــرقية بخطــاب رئيــس محكمــة‬\n‫االســتئناف رقــم ‪ 342215517‬وتاريــخ ‪1434/11/11‬ه ـ وبرفقهــا‬\n‫القــرار رقــم ‪ 34350592‬وتاريــخ ‪1434/11/5‬ه واملتضمــن مــا نصــه ‪:‬‬\n\n\n                                                                                       ‫‪470‬‬\n\f      ‫« قررنــا املصادقــة علــى احلكــم « قاضــي اســتئناف د‪ .‬ختمــه وتوقيعــه‬\n      ‫قاضــي اســتئناف ‪ .....‬ختمــه وتوقيعــه قاضي اســتئناف ختمــه ‪ ....‬وتوقيعه‬\n      ‫وحتــى ال يخفــى جــرى إحلاقــه بضبــط القضيــة وســجلها وختمــت يف‬\n      ‫الســاعة الثانيــة عشــرة ظهــرا وبــاهلل التوفيــق وصلــى اهلل وســلم علــى‬\n          ‫نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن حــرر يف ‪1434/11/25‬ه‬\n      ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n      ‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n      ‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبدينــة الدمــام برقــم ‪34289442‬‬\n      ‫وتاريــخ ‪1434/9/9‬ه ـ املقيــدة لــدى احملكمــة برقــم ‪342215517‬‬\n      ‫وتاريــخ ‪1434/9/20‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n      ‫الشــيخ املســجل برقــم ‪ 34246874‬وتاريــخ ‪1434/6/20‬ه ـ اخلــاص‬\n      ‫بدعوى‪/‬املدعــى العــام ضــد ‪ ......‬املدعــى عليــه يف قضيــة مخــدرات وقــد‬\n      ‫تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة‬\n      ‫القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم‬\n      ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف‬\n                                                                          ‫‪1434/11/3‬هــ‪.‬‬\n\n\n\n\n‫‪471‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":459,"source_page_end":471,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1b29995a37ec01410c56e6a786f4f88f2c458ed82ed999f542cf51da7c5ea430","normalized_text_hash":"a2e5fc2cb5914e5aa22a7692225241b286b7618fa6126d6c5da728fe02adb006","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p459-34246874"},{"id":"aabd901d-1d96-5602-bcb1-45966adf7fc9","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -بيع بقصد الترويج -قات -الهروب من رجال األمن -","document_number":"3433174","case_number":"3460905","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/9","year":"1434","subject":"مخدرات -بيع بقصد الترويج -قات -الهروب من رجال األمن -","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"  ‫رقم الصك‪ 3433174 :‬تاريخه‪1434/2/9:‬هـ‬\n                   ‫رقم الدعوى‪3460905:‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34177211‬تاريخه‪1434/4/2 :‬هـ‬\n\n\n‫مخــدرات ‪ -‬بيــع بقصــد الترويــج ‪ -‬قــات ‪ -‬الهــروب مــن رجــال األمــن ‪-‬‬\n     ‫املرقــم ‪.‬‬\n          ‫اإلقــرار ‪ -‬التعزيــر بالســجن واجللــد والغرامــة ورد املبلــغ ّ‬\n\n\n\n\n  ‫املادة الثالثة من قرار وزير الداخلية رقم ( ‪ ) 2057‬يف ‪1404/5/26‬هـ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام علــى املدعــى عليــه ببيــع قــات بقصــد االجتــار‬\n‫والهــروب مــن رجــال األمــن‪ ،‬طلــب إثبــات مــا أســند إليــه واحلكــم عليــه‬\n‫بعقوبــة الســجن والغرامــة واملنــع مــن الســفر ‪ ،‬حيــث وردت معلومــات‬\n‫بترويــج املدعــى عليــه للقــات فتــم التنســيق معــه مــن قبــل املصــدر علــى‬\n‫شــراء القــات برفقــة أحــد أعضــاء فرقــة املكافحــة وجــرى اســتالم‬\n‫القــات وتســليم املبلــغ املرقــم ‪ ،‬مت القبــض علــى املدعى عليــه بعد التعميم‬\n‫عليــه ‪ ،‬وأثبــت التقريــر الكيميائــي الشــرعي إيجابيــة العينــة املضبوطــة‬\n‫لنبــات القــات احملظــور ‪ ،‬وصــادق املدعــى عليــه علــى االدعــاء املوجــه‬\n‫إليــه بترويــج القــات عــن طريــق البيــع ‪ ،‬وحكمــت احملكمــة بتعزيــره‬\n‫لقــاء ذلــك بســجنه ســنتني وتغرميــه مبلــغ عشــرة آالف ريــال وتعزيــره لقــاء‬\n‫الهــروب مــن رجــال األمــن باجللــد خمســن جلــدة دفعــة واحــدة وألزمــت‬\n‫املدعــى عليــه بــرد املبلــغ الــذي اســتلمه وقــدره أربعمائــة ريــال وعــدم‬\n\n                                                                                    ‫‪472‬‬\n\f      ‫إجابــة املدعــي العــام فيمــا طلبــه مــن منــع املدعــى عليــه مــن الســفر وقنــع‬\n      ‫وصــدق‬‫املدعــى عليــه واعتــرض املدعــي مكتفي ـ ًا بالئحــة الدعــوى ‪ُ ،‬‬\n                                                ‫احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي أنــا‬\n      ‫‪.....‬القاضــي باحملكمــة اجلزائيــة باخلبــر وبنــاء علــى املعاملــة احملالــة لنــا‬\n      ‫مــن فضيلــة رئيــس احملكمــة اجلزائية يف محافظة اخلبر برقم ‪3460905‬‬\n      ‫وتاريــخ ‪ 1434/02/05‬ه ـ املقيــدة باحملكمــة برقــم ‪34305340‬‬\n      ‫وتاريــخ ‪ 1434/02/05‬ه ـ ففــي يــوم الســبت املوافــق‪1434/02/09‬‬\n      ‫ه ـ افتتحــت اجللســة الســاعة ‪ 09 : 45‬وفيهــا قــدم املدعــي العــام ‪.....‬‬\n      ‫ا‬\n      ‫الئحــة دعــوى عامــة ضــد ‪.....‬ســعودي بالســجل املدنــي رقــم(‪ ).....‬قائ ـ ً‬\n      ‫فيهــا حيــث انــه باالطــاع علــى محضــر البــاغ والقبــض والتفتيــش‬\n      ‫املعــد مــن قبــل رجــال الضبــط اجلنائــي مبكافحــة املخــدرات وعلــى‬\n      ‫محضــر القبــض املعــد مــن قبــل جــوازات اجلســر تبــن انــه يف يــوم االثنــن‬\n      ‫املوافــق ‪1433/9/18‬ه ـ ورد معلومــات مــن أحــد املصــادر الســرية عــن‬\n      ‫وجــود املدعــى عليــه يســكن الثقبــة يقــوم بترويــج القــات وأفــاد املصــدر‬\n      ‫أنــه قــام بالتنســيق معــه لشــراء قــات مببلــغ (‪ )400‬ريــال وحاليــا ينتظــره‬\n      ‫أمــام منزلــه وبنــاء علــى مــا ذكــر مت تكليــف احــد أفــراد الضبــط‬\n      ‫اجلنائــي مــن متثيــل دور املشــتري ومرافقــة املصــدر بعــد تفتيــش املصــدر‬\n      ‫وتفتيــش ســيارته إبــراء ًا للذمــة وجــرى تســليمهم املبلــغ احلكومــي املرقــم‬\n      ‫وقــدره (‪ )500‬ريــال وعلــى الفــور مت التوجــه إلــى منــزل املدعــى عليــه‬\n      ‫وعنــد وصولهــم أمــام املنــزل شــوهد شــخص أســمر البشــرة متوســط‬\n\n‫‪473‬‬\n\f‫الطــول نحيــف اجلســم و أحتــك باملصــدر ومرافقــه وبعدهــا حتركــوا‬\n‫معطــن اإلشــارة الدالــة علــى عمليــة االســتالم والتســليم وأفــاد رجــل‬\n‫املكافحــة املرافــق للمصــدر بأنــه شــاهد عمليــة االســتالم والتســليم‬\n‫وكذلــك عــرف شــكل املدعــى عليــه بإتقــان وقامــوا بتســليم اخلمــس‬\n‫مائــة ريــال وأعــاد لهــم مائــة ريــال بعــد أن ســلمهم حزمــة القــات بعدهــا مت‬\n‫االنســحاب خوفــا مــن انكشــاف املصــدر ومحاولــة القبــض عليــه الحقــا‬\n‫وقــام اجلنــدي بتســليم الكميــة املروجــة لقائــد الفرقــة ومت تســليمها‬\n‫لقســم التحــري وأتضــح أنهــا عبــارة حزمــة بهــا أغصــان خضــراء اللــون‬\n‫يشــتبه أن تكــون مــن القــات احملظــور وبلــغ وزنهــا (‪ )200‬غــرام وبعدهــا‬\n‫مت مراقبــة منــزل املدعــى عليــه عــدة أيــام ولــم يخــرج مــن املنــزل وبتاريــخ‬\n‫‪1433/10/9‬ه ـ شــوهد املدعــى عليــه خــارج املنــزل وعنــد التوجــه إليــه‬\n‫الذ بالفــرار داخــل شــقته وقــام بقفــل البــاب وعلــى الفــور مت التوجــه إلــى‬\n‫اإلدارة والتعميــم عليــه وبتاريــخ ‪1433/11/24‬ه ـ وأثنــاء مراجعــة املدعى‬\n‫عليــه جلســر‪ ...........‬بقصــد الســفر اتضــح أنــه مطلــوب ومت القبــض عليــه‬\n‫وتســليمه ملكافحــة مخــدرات الدمــام وقــد أثبــت التقريــر الكيميائــي‬\n‫الشــرعي رقــم (‪ ).....‬وتاريــخ ‪1433/10/17‬ه ـ ايجابيــة العينــات املباعــة‬\n‫لنبــات القــات احملظــور واملــدرج علــى الفقــرة رقــم(‪ )5‬مــن اجلــدول رقــم‬\n‫(‪ )4‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة وانتهــى التحقيــق‬\n‫إلــى توجيــه االتهــام ل ـ ‪..... :‬بـ‪:‬بيــع مــا وزنــه (‪ )200‬مائتــن جــرام من القات‬\n                        ‫املخــدر بقصــد االجتــار والهــروب مــن رجــال األمــن‪.‬‬\n                                                  ‫وذلك لألدلة والقرائن التالية‪:‬‬\n‫‪ -1‬محضــر البــاغ والقبــض والتفتيــش واملدونــة علــى اللفــات رقــم‬\n                    ‫(‪ )13.12.2‬مــن ملــف ضبــط إجــراءات االســتدالل ‪.‬‬\n\n\n                                                                                        ‫‪474‬‬\n\f      ‫‪ -2‬محضــر القبــض املعــد مــن قبــل رجــال الضبــط اجلنائــي بجــوازات‬\n                                    ‫جســر امللــك فهــد واملرفــق علــى اللفــة رقــم (‪.)9‬‬\n      ‫‪ -3‬التقريــر الكيمــاوي الشــرعي املشــار إليــه واملرفــق علــى اللفــة رقــم‬\n      ‫(‪ .)7‬وبالبحــث عمــا إذا كان لــه ســوابق عثــر لــه علــى ســابقة حيــازة‬\n      ‫مخــدرات اشــتباه يف اســتعمال املخــدرات وحيــث إن مــا أقــدم عليــه‬\n      ‫املدعــى عليــه ‪ -‬وهــو بكامــل أهليتــه املعتبــرة شــرعا ‪ -‬فعــل محــرم‬\n      ‫ومعاقــب عليــه شــرع ًا ونظام ـ ًا أطلــب إثبــات مــا أســند إليــه واحلكــم‬\n                                                                           ‫عليــه مبــا يلــي‪:‬‬\n      ‫‪ -1‬بعقوبــة الســجن والغرامــة واملنــع مــن الســفر الــواردة باملــادة الثالثــة‬\n      ‫مــن القــرار رقــم (‪ )2057‬وتاريــخ ‪1404/5/26‬ه ـ ووفقـ ًا للقرار الوزاري‬\n          ‫رقــم (‪ )11‬الصــادر بتاريــخ‪1374 /2/1‬ه ـ لقــاء قيامــه بترويــج القــات ‪.‬‬\n      ‫‪ -2‬مطالبــة املدعــى عليــه باملبلــغ املشــار إليــه وفــق تعميــم وزيــر الداخليــة‬\n      ‫رحمــه اهلل رقــم (‪ )15980/4/5/1‬وتاريــخ ‪1428/10/23-22‬هــ‪3 .‬ـ‬\n      ‫بعقوبــة تعزيــره تزجــره وتــردع غيــره لقــاء قيامــه بالهــروب مــن رجــال‬\n      ‫األمــن هــذه دعــواي وبســؤال املدعــى عليــه عــن الدعــوى أجــاب بقولــه‬\n      ‫مــا جــاء يف الدعــوى مــن قيامــي ببيــع مــا وزنــه (‪ )200‬مائتــي جــرام‬\n      ‫مــن نبــات القــات احملظــور هــذا صحيــح فقــد ســبق أن طلــب منــي أحــد‬\n      ‫أصدقائــي أن أبيعــه القــات احملظــور مببلــغ أربعمائــة ريــال فوافقــت علــى‬\n      ‫ذلــك وقــد حضــر لــي املشــتري بالقــرب مــن منزلنــا يف حــي ‪ .....‬وذلــك‬\n      ‫يف شــهر رمضــان املاضــي بعــد صــاة التراويــح وأعطيتــه نبــات القــات‬\n      ‫احملظــور فأعطانــي املشــتري خمســمائة ريــال وأعــدت لــه مائــة ريــال‬\n      ‫حيــث إنــي بعــت لــه القــات مببلــغ أربعمائــة ريــال ثــم انصــرف املشــتري‬\n      ‫ومرافقــه ودخلــت منزلنــا وبعــد عــدة أيــام خرجــت مــن منزلنــا فوجــدت‬\n\n\n‫‪475‬‬\n\f‫رجــال األمــن فطلبــوا منــي التوقــف فهربــت منهــم ودخلــت املنــزل وأغلقــت‬\n‫البــاب وقــد مت القبــض علـ ّـي يف تاريــخ ‪1433/11/24‬ه ـ يف جســر امللــك‬\n‫فهــد عندمــا كنــت أريــد الســفر هــذا مــا حصــل وأنــا نــادم علــى فعلــي‬\n‫وأتعهــد بعــدم تكــراره علم ـ ًا بأنــي قمــت بإنفــاق املبلــغ الــذي اســتلمته‬\n‫قيمــة للقــات ومــا ذكــره املدعــي العــام مــن ســابقتي فهــو صحيــح هكذا‬\n‫أجــاب بعــد ذلــك جــرى الرجــوع إلــى اللفــة رقــم (‪ )5‬وتضمنــت محضــر‬\n‫التحريــز وجــاء فيــه وزن نبــات القــات املــروج وهــو كمــا ذكــر املدعــي‬\n‫العــام يف دعــواه كمــا جــرى الرجــوع إلــى اللفــة رقــم (‪ )7‬وتضمنــت‬\n‫التقريــر الكيمــاوي الشــرعي وهــو كمــا ذكــر املدعــي العــام يف دعــواه‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث أقــر املدعــى عليــه‬        ‫فبنـ ً‬\n‫بقيامــه ببيــع القــات كمــا أقــر بهربــه مــن رجــال األمــن وملــا جــاء يف املــادة‬\n‫الثالثــة مــن قــرار وزيــر الداخليــة رقــم ‪ 2057‬يف ‪1404/5/26‬ه ـ وحيــث‬\n‫إنــه لــم يــرد يف هــذه املــادة عقوبــة املنــع مــن الســفر لــذا فقــد قــررت مــا‬\n‫يلــي أو ًال ‪ :‬ثبــت لــدي قيــام املدعــى عليــه بترويــج مــا وزنــه (‪ )200‬مائتــن‬\n‫جــرام مــن نبــات القــات احملظــور عــن طريــق البيــع مببلــغ أربعمائــة ريــال‬\n‫وقــررت تعزيــره لقــاء ذلــك بســجنه مــدة ســنتني اعتبــار ًا مــن تاريــخ إيقافــه‬\n‫وتغرميــه مبلــغ عشــرة آالف ريــال ثاني ـاً‪ :‬ثبــت لــدي هــروب املدعــى عليــه‬\n‫مــن رجــال األمــن وقــررت تعزيــره لقــاء ذلــك بجلــده خمســن جلــدة دفعــة‬\n‫واحــدة ثالث ـاً‪ :‬ألزمــت املدعــى عليــه بإعــادة املبلــغ الــذي اســتلمه قيمــة‬\n‫للقــات وهــو أربعمائــة ريــال رابعـاً‪ :‬عــدم إجابــة املدعــي العــام فيمــا طلبــه‬\n‫مــن منــع املدعــى عليــه مــن الســفر ومبــا تقــدم حكمــت وبعــرض احلكــم‬\n‫قنــع املدعــى عليــه ولــم يقنــع املدعــي العــام مكتفيـ ًا مبــا قــدم يف الئحــة‬\n‫الدعــوى وأقفلــت اجللســة الســاعة احلاديــة عشــر إال ربــع وصلــى اهلل وســلم‬\n\n\n                                                                                            ‫‪476‬‬\n\f                                                                        ‫علــى نبينــا محمــد‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n      ‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n      ‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة اخلبــر املكلــف برقــم‬\n      ‫‪ 34305340‬وتاريــخ ‪1434/2/12‬ه ـ املقيــدة لــدى احملكمــة برقــم‬\n      ‫‪/34/420681‬ج‪ 1‬وتاريــخ ‪1434/2/19‬ه ـ املرفــق بهــا القــرار الصــادر‬\n      ‫مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪.....‬املســجل برقــم ‪3433174‬‬\n      ‫وتاريــخ ‪1434/2/9‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام ضــد‪...../‬يف قضيــة‬\n      ‫مخــدرات وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل‬\n      ‫فيــه ‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة‬\n      ‫علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                                       ‫وســلم حــرر يف ‪1434/3/29‬ه ـ‬\n\n\n\n\n‫‪477‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":472,"source_page_end":477,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"f7909733ad51d2a40582b2f5c02c544e67e74085f605bf726355a50862f0b48c","normalized_text_hash":"83eba270cf6b5e40882471401da2b9279ce85bdc2d152e75ee12dc8fcda90555","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p472-3433174"},{"id":"f26ad317-61ff-5992-a17e-3e372a59b012","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -الوساطة يف ترويج احلشيش املخدر -إنكار -اقرار بجرم آخر -التعزير بالسجن واجللد والغرامة واملنع من السفر واملصادرة وإسقاط شريحة اجلوال.","document_number":"34172873","case_number":"3485137","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/28","year":"1434","subject":"مخدرات -الوساطة يف ترويج احلشيش املخدر -إنكار -اقرار بجرم آخر -التعزير بالسجن واجللد والغرامة واملنع من السفر واملصادرة وإسقاط شريحة اجلوال.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك‪ 34172873:‬تاريخه ‪1434/3/28:‬هـ‬\n                     ‫رقم الدعوى‪3485137:‬‬\n             ‫رقم قرار التصديق من محكمة‬\n‫االستئناف‪ 34192856:‬تاريخه‪1434/04/21 :‬هـ‬\n\n\n‫مخــدرات ‪ -‬الوســاطة يف ترويــج احلشــيش املخــدر ‪ -‬إنــكار ‪ -‬اقــرار‬\n‫بجــرم آخــر ‪ -‬التعزيــر بالســجن واجللــد والغرامــة واملنــع مــن الســفر‬\n                                  ‫واملصــادرة وإســقاط شــريحة اجلــوال‪.‬‬\n\n\n\n\n                                         ‫‪ -1‬قاعدة املرء مؤاخذ بإقراره‪.‬‬\n            ‫‪ -2‬املادة (‪ )3‬من نظام مكافحه املخدرات واملؤثرات العقلية ‪.‬‬\n          ‫‪ -3‬املادة (‪ )38‬من نظام مكافحه املخدرات واملؤثرات العقلية ‪.‬‬\n          ‫‪ -4‬املادة (‪ )53‬من نظام مكافحه املخدرات واملؤثرات العقلية ‪.‬‬\n          ‫‪ -5‬املادة (‪ )56‬من نظام مكافحه املخدرات واملؤثرات العقلية ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام علــى املدعــى عليــه بترويجــه للحشــيش املخــدر‬\n‫وطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم عليــه بالســجن واجللــد‬\n‫والغرامــة ومنعــه مــن الســفر ومصــادرة اجلــوال والغــاء الشــريحة تطبيــق‬\n‫ألحــكام نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ‪ ،‬حيــث إنــه‬\n‫ورد لفرقــة مكافحــة املخــدرات معلومــات مــن مصادرهــا الســرية عــن‬\n‫وجــود شــخص يقــوم بترويــج مــادة احلشــيش املخــدر ‪ ،‬فاســتعد املصــدر‬\n‫باالتصــال باملــروج وطلــب منــه قطعــة مــن احلشــيش واتفــق معــه علــى مبلــغ‬\n\n                                                                                    ‫‪478‬‬\n\f      ‫مقــداره ‪ 50‬ريــال ‪ ،‬وبعــد إجــراءات التســليم واالســتالم مت القبــض علــى‬\n      ‫املدعــى عليــه ‪ ،‬أثبــت التقريــر الكيميائــي الشــرعي إيجابيــة العينــة‬\n      ‫املرســلة ملــادة احلشــيش املخــدر ‪ ،‬صــادق املدعــى عليــه مــا هــو منســوب‬\n      ‫عليــه وبنــاء علــى مــا تقــدم حكمــت احملكمــة بتعزيــره بالســجن ملــدة‬\n      ‫ســنة وجلــده مائــة جلــدة وغرامــة ماليــة ‪ 1000‬ريــال ومنعــه مــن الســفر‬\n      ‫ومصــادرة الهاتــف اجلــوال وإلغــاء الشــريحة وبعــرض احلكــم علــى طــريف‬\n      ‫الدعــوى قنــع املدعــى عليــه وقــرر املدعــي العــام االعتــراض بغيــر الئحــة‬\n                                    ‫وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافــق ‪1434/3/25‬ه ـ لــدي‬\n      ‫ـاء علــى املعاملــة‬\n                         ‫أنــا ‪ ......‬القاضــي باحملكمــة اجلزائيــة بالدمــام وبنـ ً‬\n      ‫احملالــة إلينــا مــن رئيــس احملكمــة برقــم (……………‪ ).‬وتاريــخ‬\n      ‫‪1434/2/20‬ه ـ افتتحــت اجللســة وفيهــا حضــر ‪ ......‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم (‪ )......‬وقــدم املدعــي العــام ‪ ......‬الئحــة‬\n      ‫اإلدعــاء املتضمنــة بصفتــي مدعي ـ ًا عام ـ ًا بدائــرة اإلدعــاء العــام لفــرع‬\n      ‫الهيئــة باملنطقــة الشــرقية أدعــي علــى املذكــور أعــاه وباالطــاع علــى‬\n      ‫محضــر االنتقــال والقبــض والتفتيــش املعــد مــن قبــل رجــال الضبــط‬\n      ‫اجلنائــي بشــعبة مكافحــة املخــدرات بالدمــام تبــن أنــه يف يــوم األحــد‬\n      ‫املوافق ‪1433/11/14‬هـ ورد بالغ من أحد املصادر السرية عن شخص‬\n      ‫يدعــى ( ‪ )......‬يقــوم بالتوســط بترويــج احلشــيش املخــدر فتــم متكــن‬\n      ‫املصــدر مــن االتصــال عليــه وطلــب منــه قطعــة مــن احلشــيش املخــدر‬\n      ‫مببلــغ ( ‪ ) 200‬مائتــن ريــال فأجابــه بــأن يحضــر إليــه بحــي(‪ )75‬بالدمــام‬\n\n‫‪479‬‬\n\f‫لكــون احلشــيش املخــدر لــدى جــاره فتــم االنتقــال إلــى املوقــع برفقــة‬\n‫املصــدر بعــد تكليــف أحــد أفــراد الفرقــة القابضــة مبرافقتــه وتزويــده‬\n‫مببلــغ مرقــم وعنــد وصولهمــا ملنــزل الشــخص املخبــر عنــه (املتهــم‪)....../‬‬\n‫خــرج لهمــا وركــب معهمــا واتصــل بجــاره( املتهــم‪ ) ....../‬حيــث خــرج‬\n‫مــن منزلــه وتقابــل مــع ( املتهــم‪ )....../‬أمــام املنــزل ثــم رجــع ( املتهــم‪)....../‬‬\n‫للمصــدر وأفــاد بأنــه ال يوجــد لديــه ســوى قطعــة صغيــرة بخمســن ريــال‬\n‫وقــام ( املتهــم‪ )....../‬بأخــذ مبلــغ (‪ )100‬مائــة ريــال مــن املصــدر وهــي‬\n‫جــزء مــن املبلــغ املرقــم وســلمها للمــروج ( املتهــم‪ )....../‬والــذي ســلم لــه‬\n‫القطعــة املروجــة وهــي قطعــة صغيــرة ســوداء اللــون تــزن ( ‪ )2,3‬جرامــن‬\n‫وثالثــة مــن العشــرة مــن اجلــرام وأعــاد لــه مبلغ (‪ )50‬خمســون ريــال بعدها‬\n‫قــام ( املتهــم‪ )....../‬بتســليم املصــدر القطعــة املروجــة ومعهــا مبلــغ (‪)50‬‬\n‫خمســون ريــال وذهــب علــى قدميــه مســرعا حتــى اختفــى عــن األنظــار‬\n‫وعندهــا جــرى طــرق بــاب ( املتهــم‪ )...... /‬وعنــد خروجــه مت القبــض عليــه‬\n‫وبالدخــول ملنزلــه وجــد زوج أمــه الــذي حــاول التهجــم علــى الفرقــة جلهلــه‬\n‫بهويتهــم عندهــا جــرى الســيطرة علــى الوضــع وتعريفــه بهويــة الفرقــة‬\n‫وبتفتيــش غرفــة ( املتهــم‪ )....../‬لــم يعثــر علــى شــيء مــن املمنوعــات وقــد‬\n‫مت ضبــط املبلــغ املرقــم وقــدره (‪ )100‬مائــة ريــال بجيــب ( املتهــم‪)....../‬‬\n‫ولــم يقــم بإنــكار قيامــه بالترويــج وأفــاد بأنــه ال يوجــد لديــه ســوى مــا‬\n‫قــام بترويجــه وباالنتقــال ملنــزل ( املتهــم‪ )....../‬وطــرق البــاب خــرج والــده‬\n‫وأفــاد بأنــه غيــر موجــود وبالتأكــد مــن اســمه الكامــل اتضــح انــه‬\n‫يدعــى (‪ ) ......‬واثبــت التقريــر الكيمــاوي الشــرعي رقــم ( ‪ 4070‬ك ش‬\n‫) وتاريــخ ‪1433/11/20‬ه ـ ايجابيــة عينــة القطعــة املروجــة ملادة احلشــيش‬\n‫املخــدر املدرجــة باجلــدول األول فئــة(أ) مــن نظــام مكافحــة املخــدرات‬\n\n\n                                                                                              ‫‪480‬‬\n\f      ‫واملؤثــرات العقليــة وبتاريــخ ‪1434/1/14‬ه ـ مت القبــض علــى املتهــم‬\n      ‫(‪ -1 )......‬مت إيقــاف املتهــم املذكــور بالســجن رهــن احملاكمــة لكــون‬\n      ‫جرميتــه مــن اجلرائــم الكبيــرة املوجبــة لإليقــاف وفقــا للقــرار الــوزاري‬\n      ‫رقــم ( …………‪ ).‬وتاريــخ ‪1428/7/9‬ه ـ ‪-2‬مت إحالــة قضيــة املتهــم‬\n      ‫(‪ )......‬للمحكمــة اجلزائيــة بالدمــام باخلطــاب رقــم ( ………‪ ).‬وتاريــخ‬\n      ‫‪1433/12/4‬ه ـ وباســتجواب املتهــم املذكــور أقــر بقيامه باســتالم مبلغ‬\n      ‫مائــة ريــال مــن املصــدر ومــن ثــم قــام بتســليمها للمتهــم األخــر ( ‪)......‬‬\n      ‫واســتلم منــه قطعــة احلشــيش املخــدر ومبلــغ خمســون ريــال ومــن ثــم قــام‬\n      ‫بتســليمها للمصــدر وبعدهــا ذهــب ملنزلــه نافيــا هروبه بعــد واقعة الترويج‬\n      ‫وأنــه قــام ببيــع قطعــة احلشــيش املخــدر مســاعدة للمتهــم اآلخــر لكونــه‬\n      ‫جــار لــه ونفــى تعاطيــه للمخــدرات وقــد انتهــى التحقيــق إلــى اتهــام‪/‬‬\n      ‫‪ ......‬ببيــع مــا وزنــه (‪ )2,3‬جرامــن وثالثــة مــن العشــرة مــن اجلــرام مــن‬\n      ‫مــادة احلشــيش املخــدر بقصــد االجتــار وذلــك لألدلــة والقرائــن التاليــة‪:‬‬\n      ‫‪-1‬اعترافــه مبــا نســب إليــه املــدون مبحضــر اســتجوابه املرفــق علــى‬\n      ‫اللفــة رقــم (‪ -2 )40-38‬اعترافــه مبــا نــوه عنــه املــدون مبحضــر ســماع‬\n      ‫أقوالــه األوليــة علــى الصفحــة رقــم (‪ )2‬املرفــق علــى اللفــة رقــم(‪-3 )31‬‬\n      ‫محضــر القبــض املنــوه عنــه املرفــق علــى اللفــة رقــم ( ‪ -4 )12-3‬التقريــر‬\n      ‫الكيمــاوي الشــرعي املنــوه عنــه املرفــق على اللفة رقــم (‪ )25-24‬وحيث‬\n      ‫إن مــا أقــدم عليــه املتهــم املذكــور وهــو بكامــل أهليتــه املعتبــرة شــرعاً‪-‬‬\n      ‫فعــل محــرم ومعاقــب عليــه شــرع ًا ونظام ـ ًَا أطلــب إثبــات مــا أســند إليــه‬\n      ‫وفقـ ًا للفقــرة رقــم (‪ )2‬مــن املــادة رقــم(‪ )3‬مــن نظــام مكافحــة املخــدرات‬\n      ‫واملؤثــرات العقليــة واحلكــم عليــه مبــا يلــي‪-1 :‬بعقوبــة الســجن واجللــد‬\n      ‫والغرامــة الــواردة بالفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )38‬مــن النظــام‬\n\n\n‫‪481‬‬\n\f‫‪-2‬منعــه مــن الســفر إعمــاال ملقتضــى الفقــرة رقــم (‪ )1‬من املــادة رقم(‪)56‬‬\n‫مــن النظــام ‪ -3‬مصــادرة الهاتــف اجلــوال العائــد للمذكــور جــوال (‪).....‬‬\n‫يحمــل الرقــم املصنعــي ( ‪ ) ......‬مــع املطالبــة بإســقاط شــريحة الهاتــف‬\n‫النقــال وعــدم صرفهــا لنفــس املتهــم وفقــا لتعميــم ســمو وزيــر الداخليــة‬\n‫رقــم ( ‪ )9798‬وتاريخ‪1428/2/10-9‬ه ـ وبــاهلل التوفيــق وبســؤال املدعى‬\n‫عليــه أجــاب بقولــه مــا ذكــره املدعــي مــن القيــام ببيــع احلشــيش املخــدر‬\n‫فهــذا غيــر صحيــح ولكننــي قمــت بالتوســط يف بيــع قطعــة احلشــيش‬\n‫املضبوطــة يف هــذه القضيــة وأنــا تائــب ونــادم وهــذه أول مــرة يصــدر‬\n‫منــي مثــل هــذا الفعــل وقــد اســتخدمت جوالــي مــن نــوع ‪ +......‬يف عمليــة‬\n‫التوســط والتنســيق هــذه إجابتــي وبعــد تدويــن مــا ســبق جــرى االطــاع‬\n‫علــى التقريــر الكيمــاوي الشــرعي رقــم (‪4070‬ك ش) املتضمــن‬\n‫إيجابيــة عينــة القطعــة املضبوطــة يف هــذه القضيــة ملــادة احلشــيش‬\n‫املخــدر كمــا جــرى االطــاع علــى محضــر التحريــز املــدون علــى اللفــة‬\n‫الســابعة عشــرة واملتضمــن أن املضبــوط يف هــذه القضيــة عبــارة عــن‬\n‫قطعــة صغيــرة احلجــم ســوداء اللــون تــزن جرامــن وثالثــة مــن العشــرة‬\n‫مــن اجلــرام يشــتبه أن تكــون حشــيش مخــدر كمــا جــرى االطــاع‬\n‫علــى صحيفــة ســوابق املدعــى عليــه املرفقــة باملعاملــة واملتضمنــة عــدم‬\n‫وجــود ســوابق مســجلة عليــه وبتأمــل الئحــة االدعــاء تبــن أن املدعــو هــو‬\n‫مــن قــام ببيــع احلشــيش وهــو مــن مت ضبــط املبلــغ املرقــم يف جيبــه وأنــه‬\n‫قــد اعتــرف بالبيــع وإمنــا اقتصــر دور املدعــى عليــه ‪ ......‬علــى التوســط‬\n‫يف البيــع بــدون مقابــل حيــث إنــه أخــذ مــن املصــدر مائــة ريــال وســلمها‬\n‫للمــروج وأعــاد للمصــدر خمســن ريــاال ولــم يثبــت أنــه أخــذ مقابــا لقــاء‬\n‫التوســط فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث أقــر املدعــى‬\n\n\n                                                                                    ‫‪482‬‬\n\f      ‫عليــه بقيامــة بالتوســط يف عمليــة بيــع احلشــيش املخــدر وحيــث إن املــرء‬\n      ‫مؤاخــذ بإقــراره وبنــاء علــى محضــر التحريــز والتقريــر الكيمــاوي‬\n      ‫الشــرعي املشــار إليهمــا أعــاه واســتناد ًا للمــادة الثالثــة واملــادة الثامنــة‬\n      ‫والثالثــن واملــادة الثالثــة واخلمســن واملــادة السادســة واخلمســن مــن‬\n      ‫نظــام املخــدرات واملؤثــرات العقليــة وحيــث إن العقوبــات الــواردة يف‬\n      ‫املــادة الثامنــة والثالثــن تشــمل مــن قــام بالتوســط يف شــيء مــن األفعــال‬\n      ‫اجلرميــة الــواردة فيهــا ســواء كان ذلــك مبقابــل أو بــدون مقابــل كمــا‬\n      ‫هــو منصــوص املــادة وبنــاء علــى عــدم وجــود ســوابق مســجلة علــى املدعــى‬\n      ‫علــى املدعــى عليــه وحيــث أظهــر التوبــة والنــدم واســتنادا للمــادة الســتني‬\n      ‫مــن نظــام مكافحــة املخــدرات واســتنادا للمــادة التاســعة واخلمســن بعد‬\n      ‫املائــة مــن نظــام اإلجــراءات اجلزائيــة لــذا فقــد ثبــت لــدي إدانــة املدعــى‬\n      ‫عليــه بالتوســط يف بيــع قطعــة مــن احلشــيش املخــدر تــزن جرامــن وثالثــة‬\n      ‫مــن العشــرة مــن اجلــرام بــدون مقابــل واســتخدامه جوالــه املشــار إليــه‬\n      ‫يف الئحــة االدعــاء يف ذلــك وحكمــت عليــه لقــاء ذلــك مبــا يلــي‪ /‬أوال‪/‬‬\n      ‫ســجنه ســنة واحــدة اعتبــارا مــن تاريــخ إيقافــه وجلــده مائــة جلــدة مفرقــة‬\n      ‫علــى دفعتــن متســاوية وبــن كل دفعــة واألخــرى مــدة ال تقــل عــن عشــرة‬\n      ‫أيــام وإلزامــه بدفــع غرامــة ماليــة مقدارهــا ألــف ريــال ثانيــا‪ /‬منعــه مــن‬\n      ‫الســفر خــارج اململكــة مــدة ســنتني تبــدأ بعــد االنتهــاء مــن تنفيــذ عقوبــة‬\n      ‫الســجن احملكــوم بهــا ثالثــا‪ /‬مصــادرة الهاتــف اجلــوال مــن نــوع نوكيــا‬\n      ‫ذي الرقــم املصنعــي(‪ )......‬وإســقاط شــريحته وعــدم صرفهــا للمدعــى‬\n      ‫عليــه مــرة أخــرى وبعــرض احلكــم علــى املدعــى عليــه قــرر قناعتــه‬\n      ‫بــه وقــرر املدعــي العــام االعتــراض واالكتفــاء مبــا يف أوراق املعاملــة‬\n      ‫فأجيــب لطلبــه وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وبــه حــرر‬\n\n\n‫‪483‬‬\n\f                                                               ‫يف ‪1434/3/25‬ه ـ ‪.‬‬\n‫ويف يــوم الثالثــاء املوافــق ‪1434/4/30‬ه ـ افتتحــت اجللســة الســاعة‬\n‫الواحــدة والنصــف وقــد عــادت املعاملــة مــن محكمــة االســتئناف برقــم‬\n‫(‪ )......‬وتاريــخ ‪1434/4/27‬ه ـ املتعلقــة بدعــوى املدعــي العــام ‪....../‬‬\n‫وبرفقهــا القــرار الصــادر مــن الدائــرة اجلزائيــة الثانية برقــم (‪ )......‬وتاريخ‬\n‫‪1434/4/21‬ه ـ املتضمــن املصادقــة علــى احلكــم لــذا جــرى إحلــاق ذلــك‬\n‫حتــى ال يخفــى وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                                 ‫وصحبــه أجمعــن ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n‫لــدى احملكمــة برقــم وتاريــخ ‪1434/4/10‬ه ـ الــواردة مــن فضيلــة رئيس‬\n‫احملكمــة اجلزائيــة مبدينــة الدمــام برقــم وتاريــخ ‪1434/4/6‬ه ـ املرفــق‬\n‫بهــا القــرار الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ‪....../‬‬\n‫املســجل برقــم وتاريــخ ‪1434/3/28‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام‬\n‫ضــد‪ ....../‬يف قضيــة مخــدرات وقــد تضمــن القــرار حكــم فضيلتــه‬\n‫مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق‬\n‫املعاملــة قررنــا املصادقــة علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى‬\n              ‫نبينــا محمــد وآلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/4/20‬هــ‪.‬‬\n\n\n\n\n                                                                                         ‫‪484‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":478,"source_page_end":484,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ebce61e9cf5014e21e08258340a14c3b656d416653e7f62620db2a98edb97421","normalized_text_hash":"b399862fa89176c4be5fecef91dde0939d23ac07d702c16e9d2bf8a935330bb1","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p478-34172873"},{"id":"d806c4eb-2347-5773-bd19-e5fd85e31b64","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلشيش املخدر -حيازة عدد من حبوب الترامادول احملظورة بقصد التعاطي -التعزير بالسجن واجللد والغرامة واملصادرة واملنع من السفر.","document_number":"34481568","case_number":"3493681","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/03/22","year":"1434","subject":"مخدرات -ترويج احلشيش املخدر -حيازة عدد من حبوب الترامادول احملظورة بقصد التعاطي -التعزير بالسجن واجللد والغرامة واملصادرة واملنع من السفر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34481568 :‬تاريخه‪1434/03/22:‬هـ‬\n                            ‫رقم الدعوى ‪3493681:‬‬\n                    ‫رقم قرار التصديق من محكمة‬\n        ‫االستئناف‪ 34181011:‬تاريخه ‪1434/04/07‬هـ‪.‬‬\n\n\n       ‫مخــدرات ‪ -‬ترويــج احلشــيش املخــدر ‪ -‬حيــازة عــدد مــن حبــوب‬\n       ‫الترامــادول احملظــورة بقصــد التعاطــي ‪ -‬التعزيــر بالســجن واجللــد‬\n                                   ‫والغرامــة واملصــادرة واملنــع مــن الســفر‪.‬‬\n\n\n\n\n       ‫ـاب‬\n        ‫نصـ ُ‬                                                     ‫آم ُنـ ْ‬\n                                  ‫ـوا إِنَّ َــا ْال َْمـ ُـر َو ْ َ‬\n             ‫ال ْي ِسـ ُـر َوا َأل َ‬                                    ‫‪ -1‬قولــه تعالــى { َيــا َأ ُّي َهــا الَّذِ يـ َـن َ‬\n                                         ‫ـوه } ‪.‬‬  ‫اج َتن ُِبـ ُ‬                   ‫َوا َأل ْزال َُم ِر ْ ٌجــس ِّمــنْ َع َمـ ِـل َّ‬\n                                                                ‫الش ـ ْي َطانِ َف ْ‬\n       ‫‪ -2‬قولــه صلــى اهلل عليــه وســلم (كل مســكر خمــر وكل خمــر حــرام)‬\n                                                                                                                  ‫رواه مسلم‪.‬‬\n       ‫‪ -3‬ماروتــه أم ســلمه رضــي اهلل عنهــا قالــت ‪ ( :‬نهــى رســول اهلل صلــى‬\n                                                    ‫اهلل عليــه وســلم عــن كل مســكر ومفتــر )‪.‬‬\n       ‫‪ -4‬مــا قــرره الفقهــاء مــن أن العقوبــات التعزيريــة إذا متحضــت هلل تعالــى‬\n                       ‫واحتــد نوعهــا تداخلــت ‪ .‬انظــر كشــاف القنــاع (‪.)14/113‬‬\n                                      ‫‪ -5‬املواد (‪128‬و‪ )131‬من نظام اإلجراءات اجلزائية‪.‬‬\n       ‫‪ -6‬املــواد (‪ )38‬و (‪ )53‬و (‪ )56‬و (‪ )60‬و (‪ )62‬مــن نظــام مكافحــة‬\n                                                                           ‫املخــدرات واملؤثــرات العقليــة ‪. .‬‬\n       ‫‪ -7‬الفقــرة (‪ )2‬مــن املــادة (‪ )3‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                                                                     ‫العقليــة ‪.‬‬\n                                                   ‫‪ -8‬املادة (‪ )159‬من نظام اإلجراءات اجلزائية ‪.‬‬\n\n\n‫‪485‬‬\n\f‫ادعــى املدعــي العــام ضــد املدعــى عليــه ببيــع قطعــة مــن احلشــيش‬\n‫املخــدر بقصــد االجتــار وحيــازة عــدد مــن حبــوب الترامــادول احملظــور‬\n‫بقصــد التعاطــي ‪ ،‬وطلــب املدعــي العــام إثبــات مــا أســند للمدعــى عليــه‬\n‫واحلكــم عليــه بعقوبــة الســجن واجللــد والغرامــة واملنــع مــن الســفر‬\n‫ومصــادرة الهاتــف اجلــوال تطبيقـ ًا ألحــكام نظــام مكافحــة املخــدرات‬\n‫واملؤثــرات العقليــة ‪ ،‬حيــث وردت معلومــات لرجــال الضبــط اجلنائــي‬\n‫ملكافحــة املخــدرات مــن أحــد املصــادر عــن قيــام املدعــى عليــه بترويــج‬\n‫مــادة احلشــيش املخــدر ‪ ،‬مت متكــن املصــدر مــن االتصــال علــى املدعــى‬\n‫عليــه و كان ذلــك مبســمع رجــال الضبــط حيــث جــرى التنســيق علــى‬\n‫شــراء قطعــه حشــيش‪ ،‬حيــث مت تزويــد املصــدر باملبلــغ احلكومــي و‬\n‫مت تفتيشــه ‪ ،‬توجــه املصــدر علــى قدميــه حتــت نظــر الفرقــة و تقابــل‬\n‫مــع املدعــى عليــه وأعطــى املصــدر إشــارة إمتــام عمليــة الشــراء ‪ ،‬و علــى‬\n‫الفــور مت القبــض علــى املدعــى عليــه ‪ ،‬وبتفتيشــه عثــر معــه علــى اجلــوال‬\n‫الــذي مت التنســيق عليــه كمــا عثــر علــى املبلــغ احلكومــي املرقــم ‪ ،‬قــام‬\n‫املصــدر بتســليم قائــد الفرقــة قطعــه احلشــيش‪ ،‬مت مداهمة منزل املدعى‬\n‫عليــه و عثــر علــى تســع حبــات حمــراء مــن حبــوب الترامــادول احملظــور ‪،‬‬\n‫كمــا أقــر املدعــى عليــه مبــا نســب إليــه ‪ ،‬بنــاء علــى مــا تقــدم حكمــت‬\n‫احملكمــة بتعزيــره بالســجن واجللــد والغرامــة ومصــادرة اجلــوال و إلغــاء‬\n‫وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬      ‫شــريحته و املنــع مــن الســفر ُ‬\n\n\n\n\n                                                                                   ‫‪486‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......‬رئيس احملكمة اجلزائية مبحافظة‬\n      ‫القطيــف وبنــاء علــى املعاملــة احملالــة لنــا برقــم وتاريــخ ‪1434/02/26‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ……………‪.‬وتاريــخ ‪1434/02/26‬ه ـ‬\n      ‫ففــي يــوم اإلثنــن املوافق‪1434/03/16‬ه ـ افتتحــت اجللســة وفيهــا‬\n      ‫حضــر املدعــي العــام ‪ ......‬كمــا حضــر املدعــى عليــه ‪ ، ......‬ســعودي‬\n      ‫رقــم ســجله املدنــي (‪ )......‬رفــق وكيلــه ‪ ......‬ســعودي رقــم ســجله املدنــي‬\n      ‫(‪ )......‬مبوجــب الوكالــة الصــادرة مــن كاتــب عــدل محافظــة القطيــف‬\n      ‫برقــم ‪ ......‬يف ‪1434/2/20‬ه ـ املخولــة لــه املرافعــة واملدافعــة وقــدم األول‬\n      ‫الئحــة دعــوى تتضمــن بــأن املدعــى عليــه ‪ ......‬البالــغ مــن العمــر (‪)43‬‬\n      ‫ســنة محصــن ‪ ،‬موظــف أهلــي ‪ ،‬أوقــف بتاريــخ ‪1434/1/13‬ه ـ وأحيــل‬\n      ‫لســجن محافظــة القطيــف و أنــه بتاريــخ ‪1434/1/12‬ه ـ وردت معلومات‬\n      ‫لرجــال الضبــط اجلنائــي مبكافحــة املخــدرات عــن قيــام املدعــى عليــه‬\n      ‫بترويــج مــادة احلشــيش املخــدر وأفــاد أحــد املصــادر بأنــه يســتطيع‬\n      ‫اإلطاحــة بــه باجلــرم املشــهود ومت متكــن املصــدر مــن االتصــال علــى‬\n      ‫املدعــى عليــه وكانــت املكاملــة حتــت مســامع رجــال الضبــط اجلنائــي‬\n      ‫حيــث جــرى التنســيق مــع املدعــى عليــه علــى قطعــة حشــيش مببلــغ‬\n      ‫خمســمائة ريــال و كان املوعــد أمــام املنــزل وعلــى الفــور مت االنتقــال إلى‬\n      ‫املوقــع ومت تزويــد املصــدر باملبلــغ احلكومــي املرقــم ومت تفتيــش املصــدر‬\n      ‫وبعــد حلظــات توجــه املصــدر علــى قدميــه حتــت أنظــار الفرقــة و تقابــل‬\n      ‫معــه وقــام املصــدر بإعطــاء إشــارة إمتــام عمليــة الشــراء وعلــى الفــور مت‬\n      ‫القبــض عليــه وبتفتيشــه عثــر معــه علــى اجلــوال الــذي مت التنســيق عليــه‬\n\n‫‪487‬‬\n\f‫وقــد عثــر علــى املبلــغ احلكومــي املرقــم كمــا قــام املصــدر بتســليم قائــد‬\n‫الفرقــة قطعــة بنيــة اللــون تــزن (‪ )24,5‬أربعــة وعشــرين جرام ـ ًا ونصــف‬\n‫اجلــرام و بنــاء علــى أمــر ســعادة مديــر مكافحــة املخــدرات بالشــرقية‬\n‫مت مداهمــة منــزل املدعــى عليــه ومت العثــور علــى عــدد ( ‪ ) 9‬تســع حبــات‬\n‫حمــراء اللــون مــن حبــوب الترامــادول احملظــور أثبت التقريــر الكيماوي‬\n‫الشــرعي رقــم (‪ )....‬وتاريــخ ‪1434/1/24‬ه ـ املتضمــن إيجابيــة عينــة‬\n‫القطعــة املروجــة ملــادة احلشــيش املخــدر و املــدرج يف اجلــدول األول فئــة‬\n‫(أ) امللحــق بنظــام مكافحــة املخــدرات كمــا أثبــت التقريــر الكيمــاوي‬\n‫الشــرعي املشــار إليــه إيجابيــة عينــة احلبــوب لعقــار الترامــادول احملظــور‬\n‫و املــدرج يف اجلــدول األول فئــة (هــ) امللحــق بنظــام مكافحــة املخــدرات‬\n‫وباســتجواب املدعــى عليــه أقــر بصحــة واقعــة الضبــط وأنــه اتصــل عليــه‬\n‫شــخص واتفــق مبقابلتــه عنــد منزلــه لكونــه يطالبــه مبلــغ مالــي وقــدره‬\n‫(‪ )500‬ريــال وقــام باالتصــال عليــه وقابلــه عنــد املنــزل و أخــذ املبلــغ منــه‬\n‫كمــا أقــر بحيازتــه ملــا عــدده (‪ )9‬تســعة حبــات وهــي عائــدة لــه بقصــد‬\n‫االســتخدام و أنــه قــام بشــرائها مــن شــخص مصــري ال يعرفــه وهــي‬\n‫لقصد االســتخدام وأخذها للتنشــيط اجلنســي‪ .‬وقد انتهى التحقيق معه‬\n‫إلــى توجيــه االتهــام إليــه ببيــع قطعــة تــزن (‪ )24,5‬أربعــة وعشــرين جرامــا‬\n‫ونصــف اجلــرام مــن مــادة احلشــيش املخــدر بقصــد االجتــار وحيــازة مــا‬\n‫عــدده (‪ )9‬تســع حبــات مــن عقــار الترامــادول احملظــور بقصــد التعاطــي‬\n‫‪ ،‬وذلــك لألدلــة والقرائــن املوضحــة بالالئحــة وبالبحــث عمــا إذا كان‬\n‫لــه ســوابق عثــر لــه علــى ســابقة حيــازة مســكر‪ .‬وحيــث إن مــا أقــدم عليه‬\n‫املذكــور وهــو بكامــل أهليتــه املعتبــرة شــرعا فعل محــرم ومعاقب عليه‬\n‫وفقــا للفقــرة‬\n             ‫شــرع ًا ونظام ـ ًا أطلــب مــا يلــي‪ :‬أوال‪ :‬إثبــات مــا أســند إليــه ً‬\n\n                                                                                         ‫‪488‬‬\n\f      ‫رقــم (‪ )2‬مــن املــادة رقــم (‪ )3‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n      ‫العقليــة واحلكــم عليهمــا مبــا يلــي‪ -1 :‬بعقوبــة الســجن واجللــد والغرامــة‬\n      ‫الــواردة بالفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )38‬مــن النظــام مــع مراعــاة‬\n      ‫املــادة (‪ )62/1‬مــن النظــام ‪ -2‬منعــه مــن الســفر إعمــاال ملقتضــى الفقــرة‬\n      ‫رقــم (‪ )1‬مــن املــادة رقــم (‪ )56‬مــن النظــام ‪ .‬ثانيــا‪ :‬مصــادرة الهاتف اجلوال‬\n      ‫العائــد للمتهــم املذكــور و الــذي مــن نــوع ‪ .....‬ويحمــل الرقــم املصنعــي‬\n      ‫( ‪ ) ......‬و يحمــل رقــم االتصــال (‪ )......‬الســتخدامه يف الترويــج وفقــا‬\n      ‫للفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )53‬مــن النظــام ‪ ،‬مــع املطالبــة بإســقاط‬\n      ‫شــريحة الهاتــف النقــال وعــدم صرفهــا لنفــس املتهــم وفقــا لتعميــم ســمو‬\n      ‫وزيــر الداخليــة رقــم (‪ ).....‬وتاريــخ ‪1429/2/10-9‬هــ‪ .‬هــذه دعــواي‬\n      ‫ا مــا ذكــره املدعــي العــام مــن‬  ‫وبعرضهــا علــى املدعــى عليــه أجــاب قائـ ً‬\n      ‫القبــض علــي يف التاريــخ املذكــور وقيامــي ببيــع قطعــة حشــيش تــزن‬\n      ‫(‪ )24,5‬أربعــة وعشــرين جرام ـ ًا ونصــف اجلــرام وحيــازة مــا عــدده (‪)9‬‬\n      ‫تســع حبــات مــن عقــار الترامــادول احملظــور بقصــد التعاطــي وإجــراء‬\n      ‫االتصــال إلمتــام بيــع املخــدر بجهــاز اجلــوال والشــريحة املشــار لهمــا يف‬\n      ‫الئحــة الدعــوى كل ذلــك صحيــح لكننــي نــادم علــى مــا بــدر منــي‬\n      ‫وأنــا تائــب ولــدي زوجــة وأطفــال هكــذا أجــاب وبدراســة املعاملــة جــرى‬\n      ‫االطــاع علــى التقريــر الكيمــاوي وصحيفة الســوابق املشــار لهما أعاله‬\n      ‫فوجدتهــا كمــا ذكــر املدعــي العــام فجــرى ســؤال املدعــى عليــه هــل‬\n      ‫ميتهــن االجتــار باملخــدرات قــال ال فأنــا موظــف أهلــي ولــدي ورش ولســت‬\n      ‫معتــاد ًا علــى بيــع املخــدرات فجــرى ســؤال املدعــي العــام ألديــه بينــة علــى‬\n      ‫مــا ادعــاه مــن أن البيــع مــن قصــد االجتــار قــال ال بينــة لــدي ســوى مــا‬\n      ‫جــاء يف محضــر البــاغ والقبــض والتفتيــش املــدون علــى الصفحــات‬\n\n\n‫‪489‬‬\n\f‫رقــم (‪ )2‬و(‪ )11‬مــن ملــف ضبــط إجــراءات االســتدالل وباالطــاع عليــه‬\n‫وجــدت البــاغ يتضمــن ورود معلومــات عــن شــخص ب‪ ....‬يدعــى ‪.....‬‬\n‫يقــوم بترويــج مــادة احلشــيش املخــدر كمــا أن واقعــة القبــض والتفتيــش‬\n‫موافقــة ملــا جــاء يف دعــوى املدعــي العــام فجــرى ســؤال الطرفــن ألديهــم‬\n‫مــا يريــدان إضافتــه فقــاال ليــس لدينــا مــا نضيــف ‪.‬فبنــاء علــى مــا تقــدم‬\n‫وحيــث تتلخــص دعــوى املدعــي العــام يف اتهــام املدعــى عليــه ببيــع قطعــة‬\n‫تــزن (‪ )24,5‬أربعــة وعشــرين جرامــا ونصــف اجلــرام مــن مــادة احلشــيش‬\n‫املخــدر بقصــد االجتــار وحيــازة مــا عــدده (‪ )9‬تســع حبــات مــن عقــار‬\n‫الترامــادول احملظــور بقصــد التعاطــي وألن هــذه احملكمــة مختصــة‬\n‫بنظــر هــذه الدعــوى بنــاء علــى املــواد (‪ )131،128‬مــن نظــام اإلجــراءات‬\n‫اجلزائيــة وإلقــرار املدعــى عليــه وهــو بكامــل أهليته ببيع قطعة احلشــيش‬\n‫املخــدر املذكــورة وحيــازة (‪ )9‬تســع حبــات مــن عقــار الترامــادول‬\n‫احملظــور بقصــد التعاطــي و إلنــكاره االجتــار يف بيــع املخــدرات و ألن‬\n‫وصــف االجتــار يســتلزم ثبــوت قيــام املدعــى عليــه باحتــراف هــذا العمــل‬\n‫و اتخــاذه مهنــة لــه ممــا يســتلزم تكــرار ممارســته فــا يعــد كل بيــع‬\n‫أو شــراء جتــارة و إن كانــا مــن أفعالهــا و حيــث لــم يتضمــن محضــر‬\n‫القبــض والتفتيــش املشــار لــه أعــاه العثــور علــى كميــات أخــرى مــن‬\n‫املــواد املخــدرة ســوى حبــوب الترامــادول كمــا لــم أجــد يف أقــوال املدعى‬\n‫عليــه حتقيق ـ ًا مــا يــدل علــى االجتــار كمــا أن البــاغ منســوب ملصــدر‬\n‫مجهــول و لــم تتضمــن صحيفــة ســوابقه ثبــوت إدانتــه بترويــج املخــدرات‬\n‫ولعــدم إقامــة املدعــي العــام بينــة موصلــة علــى أن القصــد هــو االجتــار‬\n‫فــإن الوصــف األقــرب ملــا قــام بــه املدعــى عليــه هــو الترويــج مبقابــل وألن‬\n‫مــا أقــدم عليــه مــن بيــع احلشــيش املخــدر و تعاطيــه و وحيــازة احلبــوب‬\n\n\n                                                                                       ‫‪490‬‬\n\f      ‫احملظــورة أفعــال محرمــة شــرع ًا لقولــه تعالــى ((إمنــا اخلمــر وامليســر‬\n      ‫واألنصــاب واألزالم رجــس مــن عمــل الشــيطان فاجتنبــوه)) املائــدة‪90:‬‬\n      ‫ولقولــه صلــى اهلل عليــه وســلم (( كل مســكر خمــر وكل خمــر حــرام‬\n      ‫)) رواه مســلم و ملــا روتــه أم ســلمة رضــي اهلل عنهــا قالــت « نهــى رســول‬\n      ‫اهلل صلــى اهلل عليــه و ســلم عــن كل مســكر و مفتــر» رواه أحمــد و‬\n      ‫أبــو داود كمــا أنهــا أفعــال مجرمــة نظامـ َا وفقـ ًا للفقــرة (‪ )2‬مــن املــادة (‬\n      ‫‪ ) 3‬مــن نظــام مكافحــة املخــدرات و ملــا نصــت عليــه املــادة ( ‪ )159‬مــن‬\n      ‫نظــام اإلجــراءات اجلزائيــة مــن أن احملكمــة ال تتقيــد بالوصــف الــوارد‬\n      ‫يف الئحــة الدعــوى و أن عليهــا أن تعطــي الفعــل الوصــف الــذي يســتحقه‬\n      ‫لهــذا كلــه فقــد ثبــت لــدي إدانــة املدعــى عليــه احلاضــر ‪ ......‬باآلتــي‪:‬‬\n      ‫أو ًال ‪ :‬بيــع قطعــة حشــيش تــزن (‪ )24,5‬أربعــة وعشــرون جرامــا ونصــف‬\n      ‫اجلــرام بقصــد الترويــج مبقابــل‪ .‬ثانيـ ًا ‪:‬حيــازة مــا عــدده (‪ )9‬تســع حبــات‬\n      ‫مــن عقــار الترامــادول احملظــور بقصــد التعاطــي و ملــا قــرر الفقهاء من أن‬\n      ‫العقوبــات التعزيريــة إذا متحضــت هلل تعالــى واحتــد نوعهــا تداخلــت أنظر‬\n      ‫كشــاف القناع (‪ )113/14‬وبعد االطالع على املواد(‪)62،56،53،38‬‬\n      ‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ونظــر ًا لقلــة الكميــة‬\n      ‫املروجــة وعــدم وجــود ســوابق علــى املدعــى عليــه بهــذا اخلصــوص وملــا‬\n      ‫أبــداه مــن االعتــراف وإعــان التوبــة والظــروف االجتماعيــة وبنــاء علــى‬\n      ‫املــادة (‪ )60‬مــن نظــام مكافحــة املخــدرات فقــد حكمــت عليــه باآلتــي ‪:‬‬\n      ‫أوال‪ :‬ســجنه ثــاث ســنوات وتغرميــه ألفــن وخمســمائة ريــال وجلــده مائــة‬\n      ‫وخمســن جلــدة مفرقــة علــى ثــاث دفعــات متســاويات ثاني ـاً‪ :‬مصــادرة‬\n      ‫جهــاز الهاتــف اجلــوال العائــد للمدعــى عليــه مــن نــوع ‪ .....‬ويحمــل الرقــم‬\n      ‫املصنعــي ( ‪ ) ......‬و الشــريحة التــي حتمــل الرقــم (‪ )......‬وعــدم صرفهــا‬\n\n\n‫‪491‬‬\n\f‫لنفــس املتهــم ثالثـاً‪ :‬منعــه مــن الســفر خــارج اململكــة مــدة ثــاث ســنوات‬\n‫تبــدأ بعــد انتهــاء تنفيــذ عقوبــة الســجن وبإعــان احلكــم قنــع بــه املدعــى‬\n‫عليــه وقــرر املدعــي العــام اعتراضــه وطلــب رفــع املعاملــة حملكمــة‬\n‫االســتئناف دون تقــدمي الئحــة اعتراضيــة وأغلقــت اجللســة وصلــى اهلل‬\n                                      ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......‬رئيــس احملكمــة اجلزائيــة‬\n‫مبحافظــة القطيــف فقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫باملنطقــة الشــرقية وبرفقهــا القــرار رقــم يف ‪1434/4/7‬ه ـ املتضمــن‬\n           ‫املصادقــة علــى احلكــم و للبيــان أحلــق يف ‪1434/4/17‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n‫لــدى احملكمــة برقــم وتاريــخ ‪1434/3/25‬ه ـ الــواردة مــن فضيلــة رئيس‬\n‫احملكمــة اجلزائيــة مبحافظــة القطيــف الشــيخ‪ ....../‬برقــم وتاريــخ‬\n‫‪1434/3/22‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلتــه املســجل برقــم‬\n‫وتاريــخ ‪1434/3/17‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام ضــد‪ ....../‬يف‬\n‫قضيــة مخــدرات وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون‬\n‫ومفصــل فيــه‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا‬\n‫املصادقــة علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                      ‫وصحبــه وســلم‪ .‬حــرر يف ‪1434/4/7‬هــ‪.‬‬\n\n\n\n\n                                                                                         ‫‪492‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":485,"source_page_end":492,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"66f23934deffbb13ec4c00c5ea76500b35a15dfd42bac63100e633ca5e6c74ee","normalized_text_hash":"df0f7af21f6e0ff5ab4e83efb0007cfd5cbf5bfb06601f89dfdfd4ea151d79da","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p485-34481568"}]$archive_payload$::jsonb AS data)
